def _carregar_mpl():
    global Figure, FigureCanvasTkAgg, HAS_MPL
    if Figure is not None: return True
    try:
        import matplotlib
        matplotlib.use("TkAgg")
        from matplotlib.figure import Figure as _Fig
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg as _Canvas
        import warnings
        warnings.filterwarnings("ignore", message=".*[Tt]ight.?layout.*")
        Figure, FigureCanvasTkAgg = _Fig, _Canvas
        return True
    except Exception:
        HAS_MPL = False
        return False


