def _log(msg):
    try: print(f"[TabWon] {msg}", flush=True)
    except Exception: pass
    try: _LOG_MEMORIA.append(f"{datetime.now().strftime('%d/%m %H:%M:%S')}  {msg}")
    except Exception: pass


def _normalizar_texto(texto):
    if texto is None: return ""
    return (unicodedata.normalize('NFKD', str(texto))
            .encode('ASCII', 'ignore').decode('ASCII').strip().lower())


def _prefixo_alinhado(prefixo, widget):
    try:
        try: f_ = widget.cget("font")
        except Exception: f_ = ""
        fonte = tkfont.Font(font=(str(f_) if str(f_) else "TkTextFont"))
        alvo = max(fonte.measure(p) for p in (PREFIXO_SUPER, PREFIXO_LOG, PREFIXO_SQL))
        base = prefixo.rstrip()
        res = base
        for _ in range(40):
            if fonte.measure(res + " ") >= alvo: break
            mais = res + "\u200a"
            if fonte.measure(mais) <= fonte.measure(res): break
            res = mais
        return res + " "
    except Exception:
        return prefixo


def centralizar(janela, parent=None):
    janela.update_idletasks()
    w = janela.winfo_width() or 400
    h = janela.winfo_height() or 300
    if parent:
        px, py = parent.winfo_rootx(), parent.winfo_rooty()
        pw, ph = parent.winfo_width(), parent.winfo_height()
        x = px + (pw - w) // 2; y = py + (ph - h) // 2
    else:
        sw, sh = janela.winfo_screenwidth(), janela.winfo_screenheight()
        x = (sw - w) // 2; y = (sh - h) // 2
    try:
        sw, sh = janela.winfo_screenwidth(), janela.winfo_screenheight()
        x = max(0, min(x, sw - w)); y = max(0, min(y, sh - h - 40))
    except Exception: pass
    janela.geometry(f"{w}x{h}+{x}+{y}")
    try: janela.lift(); janela.focus_force()
    except Exception: pass


def _bind_escape(janela):
    try:
        janela.bind("<Escape>", lambda e: janela.destroy()); janela.focus_force()
    except Exception: pass


