_CACHE_HEX = {}
_CACHE_PALETAS = {}
_OPC_POR_CLASSE = {}
_IMAGENS_REG = {}


def _para_hex(v):
    if not isinstance(v, str): return None
    s = v.strip().lower()
    if not s: return None
    if s in _CACHE_HEX: return _CACHE_HEX[s]
    h = None
    if re.fullmatch(r"#[0-9a-f]{6}", s): h = s
    elif re.fullmatch(r"#[0-9a-f]{3}", s): h = "#" + "".join(c * 2 for c in s[1:])
    elif s in _NOMES_COR: h = _NOMES_COR[s]
    elif _TEMA["root"] is not None:
        try:
            r, g, b = _TEMA["root"].winfo_rgb(v)
            h = "#%02x%02x%02x" % (r // 256, g // 256, b // 256)
        except Exception: h = None
    _CACHE_HEX[s] = h
    return h


def _cor_heuristica(tipo, h):
    import colorsys
    r, g, b = (int(h[i:i + 2], 16) / 255 for i in (1, 3, 5))
    hh, l, s = colorsys.rgb_to_hls(r, g, b)
    if tipo == "f":
        if l >= 0.6: l, s = 0.12 + (1 - l) * 0.35, s * 0.5
        else: l = l * 0.85
    else:
        if l <= 0.45: l = 0.92 - l * 0.4
        else: l = max(l, 0.7)
    r, g, b = colorsys.hls_to_rgb(hh, l, s)
    return "#%02x%02x%02x" % (int(r * 255), int(g * 255), int(b * 255))


def _traduzir_cor(tipo, v):
    if _TEMA["identidade"] or not isinstance(v, str) or not v.strip(): return v
    h = _para_hex(v)
    if not h: return v
    papel = _MAPA_PAPEL[tipo].get(h)
    pal = _TEMA["paleta"]
    if papel and papel in pal: return pal[papel][1 if _TEMA["escuro"] else 0]
    if _TEMA["escuro"]: return _cor_heuristica(tipo, h)
    return v


def _tipo_opcao(k):
    k = k.rstrip("_").lstrip("-")
    if k in _OPC_FUNDO or k == "fill": return "f"
    if k in _OPC_TEXTO or k == "outline": return "t"
    return None


def _traduzir_dict(d):
    if not d or _TEMA["identidade"] or not isinstance(d, dict): return d
    novo = None
    for k, v in d.items():
        t = _tipo_opcao(k) if isinstance(k, str) else None
        if t and isinstance(v, str):
            nv = _traduzir_cor(t, v)
            if nv != v:
                if novo is None: novo = dict(d)
                novo[k] = nv
    return novo if novo is not None else d


_APELIDOS_COR = {"bg": "background", "fg": "foreground"}


def _cores_de(d):
    if not isinstance(d, dict): return {}
    return {_APELIDOS_COR.get(k.rstrip("_"), k.rstrip("_")): v for k, v in d.items()
            if isinstance(k, str) and _tipo_opcao(k) and isinstance(v, str)}


_ORIG_OPTIONS = tk.Misc._options
_ORIG_CONFIGURE = tk.Misc._configure
_ORIG_BW_INIT = tk.BaseWidget.__init__
_ORIG_TV_TAG = ttk.Treeview.tag_configure
_ORIG_CREATE_TEXT = tk.Canvas.create_text
_ORIG_CANVAS_CREATE = tk.Canvas._create
_ORIG_CANVAS_DELETE = tk.Canvas.delete
_ORIG_LB_DELETE = tk.Listbox.delete


def _options_tema(self, cnf, kw=None):
    if not _TEMA["identidade"] and not _TEMA["pausa"]:
        if kw:
            cnf = tk._cnfmerge((cnf, kw)); kw = None
        if isinstance(cnf, dict): cnf = _traduzir_dict(cnf)
    return _ORIG_OPTIONS(self, cnf, kw)


def _configure_tema(self, cmd, cnf, kw):
    try:
        d = tk._cnfmerge((cnf, kw)) if kw else cnf
        cores = _cores_de(d)
        if cores:
            if cmd == "configure":
                self.__dict__.setdefault("_cores_orig", {}).update(cores)
            elif isinstance(cmd, tuple) and len(cmd) == 3 and cmd[0] == "tag" and cmd[1] == "configure":
                self.__dict__.setdefault("_tags_orig", {}).setdefault(cmd[2], {}).update(cores)
            elif isinstance(cmd, tuple) and len(cmd) == 2 and cmd[0] == "itemconfigure" and isinstance(self, tk.Listbox):
                try: idx = int(self.index(cmd[1]))
                except Exception: idx = None
                if idx is not None: self.__dict__.setdefault("_litens_orig", {}).setdefault(idx, {}).update(cores)
    except Exception: pass
    return _ORIG_CONFIGURE(self, cmd, cnf, kw)


def _opcoes_cor_widget(w):
    try: cls = w.winfo_class()
    except Exception: return []
    if cls not in _OPC_POR_CLASSE:
        try: _OPC_POR_CLASSE[cls] = [k for k in w.keys() if _tipo_opcao(k) and k not in ("fill", "outline", "bg", "fg")]
        except Exception: _OPC_POR_CLASSE[cls] = []
    return _OPC_POR_CLASSE[cls]


def _cor_bruta(w, opcao, valor):
    try: w.tk.call(w._w, "configure", "-" + opcao, valor)
    except Exception: pass


def _tematizar_widget(w, recolorir=True):
    if isinstance(w, ttk.Widget): return
    orig = w.__dict__.setdefault("_cores_orig", {})
    for op in _opcoes_cor_widget(w):
        if op not in orig:
            try: orig[op] = str(w.cget(op))
            except Exception: continue
        if recolorir:
            _cor_bruta(w, op, _traduzir_cor(_tipo_opcao(op), orig[op]))


def _bw_init_tema(self, master, widgetName, cnf={}, kw={}, extra=()):
    _ORIG_BW_INIT(self, master, widgetName, cnf, kw, extra)
    try:
        cores = _cores_de(tk._cnfmerge((cnf, kw)) if kw else cnf)
        if cores: self.__dict__.setdefault("_cores_orig", {}).update(cores)
        if not _TEMA["identidade"]: _tematizar_widget(self)
    except Exception: pass


def _tv_tag_tema(self, tagname, option=None, **kw):
    if kw:
        cores = _cores_de(kw)
        if cores: self.__dict__.setdefault("_ttags_orig", {}).setdefault(tagname, {}).update(cores)
        kw = _traduzir_dict(kw)
    return _ORIG_TV_TAG(self, tagname, option, **kw)


def _create_text_tema(self, *args, **kw):
    if not _TEMA["identidade"] and isinstance(kw.get("fill"), str):
        orig = kw["fill"]
        kw = dict(kw); kw["fill"] = _traduzir_cor("t", orig)
        _TEMA["pausa"] += 1
        try: item = _ORIG_CREATE_TEXT(self, *args, **kw)
        finally: _TEMA["pausa"] -= 1
        try: self.__dict__.setdefault("_itens_orig", {})[item] = ("text", {"fill": orig})
        except Exception: pass
        return item
    return _ORIG_CREATE_TEXT(self, *args, **kw)


def _canvas_create_tema(self, itemType, args, kw):
    item = _ORIG_CANVAS_CREATE(self, itemType, args, kw)
    try:
        d = kw if isinstance(kw, dict) else {}
        if args and isinstance(args[-1], dict): d = dict(args[-1], **d)
        cores = {k: v for k, v in d.items() if k in ("fill", "outline", "activefill", "activeoutline") and isinstance(v, str) and v}
        if cores: self.__dict__.setdefault("_itens_orig", {})[item] = (itemType, cores)
    except Exception: pass
    return item


def _canvas_delete_tema(self, *args):
    try:
        reg = self.__dict__.get("_itens_orig")
        if reg:
            if "all" in args: reg.clear()
            else:
                for a in args:
                    if isinstance(a, int): reg.pop(a, None)
    except Exception: pass
    return _ORIG_CANVAS_DELETE(self, *args)


def _lb_delete_tema(self, first, last=None):
    try:
        reg = self.__dict__.get("_litens_orig")
        if reg:
            ini = int(self.index(first))
            for k in [k for k in reg if k >= ini]: reg.pop(k, None)
    except Exception: pass
    return _ORIG_LB_DELETE(self, first, last)


tk.Listbox.delete = _lb_delete_tema
