_IDIOMAS_PADRAO = ["TabWon_lng_PTBR.lng", "TabWon_lng_ENUS.lng", "TabWon_lng_ESES.lng"]
IDIOMA_PADRAO = "TabWon_lng_PTBR.lng"
_I18N = {"ativo": False, "pausa": 0, "dic": {}, "tpl": [], "cache": {}, "arquivo": "", "codigo": "PTBR",
         "nome": "Português (Brasil)"}
_RE_I18N_BORDA = re.compile(r"^(\s*)(.*?)(\s*)$", re.S)
_RE_I18N_MARCA = re.compile(r"\{(\d+)\}")
_RE_I18N_SUFIXO = re.compile(r"^(.*?\S)(\s*[▲▼▶◀↑↓]+)$", re.S)
_RE_I18N_PREFIXO = re.compile("^([^\\w\"'(\\[{¿¡]+)(\\S.*)$", re.S)


def _i18n_desescapar(v):
    saida = []; i = 0
    while i < len(v):
        c = v[i]
        if c == "\\" and i + 1 < len(v):
            n = v[i + 1]
            saida.append({"n": "\n", "t": "\t", '"': '"', "\\": "\\"}.get(n, "\\" + n)); i += 2; continue
        saida.append(c); i += 1
    return "".join(saida)


def _ler_lng(caminho):
    dados = {}
    try:
        with open(caminho, "r", encoding="utf-8-sig") as f: linhas = f.read().splitlines()
    except Exception as ex:
        _log(f"Idioma ilegível {caminho}: {ex}"); return dados
    for linha in linhas:
        s = linha.strip()
        if not s or s.startswith(("#", ";")) or (s.startswith("[") and s.endswith("]")) or "=" not in s: continue
        k, v = s.split("=", 1); k = k.strip(); v = v.strip()
        if not k: continue
        if v.startswith('"'):
            j = 1; fim = None
            while j < len(v):
                if v[j] == "\\": j += 2; continue
                if v[j] == '"': fim = j; break
                j += 1
            v = v[1:fim] if fim is not None else v[1:]
        else:
            if " #" in v: v = v[:v.index(" #")]
            v = v.strip()
        dados[k] = _i18n_desescapar(v)
    return dados


def _nome_idioma(caminho):
    try:
        with open(caminho, "r", encoding="utf-8-sig") as f:
            for linha in f:
                s = linha.strip()
                if s.lower().startswith("idioma_nome") and "=" in s:
                    v = s.split("=", 1)[1].strip()
                    if v.startswith('"'): v = v[1:].split('"', 1)[0]
                    if v: return v
    except Exception: pass
    base = os.path.splitext(os.path.basename(caminho))[0]
    return base.replace("TabWon_lng_", "")


def _codigo_idioma(arquivo):
    base = os.path.splitext(os.path.basename(arquivo or ""))[0]
    return (base[len("TabWon_lng_"):] if base.startswith("TabWon_lng_") else base).upper() or "PTBR"


def _i18n_definir(arquivo):
    _I18N.update(ativo=False, dic={}, tpl=[], cache={}, arquivo="", codigo="PTBR", nome="Português (Brasil)")
    if not arquivo: return False
    caminho = os.path.join(PASTA_CONFIGS, arquivo)
    if not os.path.exists(caminho): return False
    dados = _ler_lng(caminho)
    dic = {}; tpl = []
    for chave, pt in TEXTOS_PT.items():
        tr = dados.get(chave)
        if tr is None or tr == "": continue
        if _RE_I18N_MARCA.search(pt):
            partes = _RE_I18N_MARCA.split(pt)
            rx = "^"; literais = []
            for i, p in enumerate(partes):
                if i % 2 == 0:
                    rx += re.escape(p)
                    if p.strip(): literais.append(p)
                else: rx += f"(?P<g{p}>.*?)"
            if not literais: continue
            try: tpl.append((re.compile(rx + "$", re.S), max(literais, key=len), tr, sum(len(x) for x in literais)))
            except Exception: pass
        else:
            dic[pt] = tr
    tpl.sort(key=lambda t: -t[3])
    _I18N.update(ativo=True, dic=dic, tpl=tpl, cache={}, arquivo=arquivo, codigo=_codigo_idioma(arquivo),
                 nome=dados.get("Idioma_nome") or _nome_idioma(caminho))
    return True


def _i18n_nucleo(s):
    m = _RE_I18N_BORDA.match(s)
    ini, meio, fim = m.group(1), m.group(2), m.group(3)
    if not meio: return None
    r = _I18N["dic"].get(meio)
    if r is not None: return ini + r + fim
    for rx, lit, tr, _ in _I18N["tpl"]:
        if lit not in meio: continue
        mm = rx.match(meio)
        if not mm: continue
        grupos = mm.groupdict()
        def _valor(m_):
            v = grupos.get("g" + m_.group(1), "")
            if v is None: return ""
            vm = _RE_I18N_BORDA.match(v)
            return vm.group(1) + _I18N["dic"].get(vm.group(2), vm.group(2)) + vm.group(3)
        return ini + _RE_I18N_MARCA.sub(_valor, tr) + fim
    return None


def _i18n_um(s):
    r = _i18n_nucleo(s)
    if r is None:
        mp = _RE_I18N_PREFIXO.match(s)
        if mp:
            q = _i18n_nucleo(mp.group(2))
            if q is not None: r = mp.group(1) + q
    if r is None:
        ms = _RE_I18N_SUFIXO.match(s)
        if ms:
            q = _i18n_nucleo(ms.group(1))
            if q is not None: r = q + ms.group(2)
    return r


def _t(s):
    if not _I18N["ativo"] or not isinstance(s, str) or not s.strip(): return s
    c = _I18N["cache"].get(s)
    if c is not None: return c
    r = _i18n_um(s)
    if r is None and "\n" in s:
        partes = s.split("\n"); mudou = False
        for i, p in enumerate(partes):
            q = _i18n_um(p) if p.strip() else None
            if q is not None: partes[i] = q; mudou = True
        if mudou: r = "\n".join(partes)
    if r is None: r = s
    if len(_I18N["cache"]) > 20000: _I18N["cache"].clear()
    _I18N["cache"][s] = r
    return r


def _i18n_livre(w):
    try: return not w.__dict__.get("_sem_traducao")
    except Exception: return True


_ORIG_OPTIONS_I18N = tk.Misc._options
_ORIG_CGET_I18N = tk.Misc.cget
_ORIG_WM_TITLE_I18N = tk.Wm.wm_title
_ORIG_TV_HEADING_I18N = ttk.Treeview.heading
_ORIG_TV_INSERT_I18N = ttk.Treeview.insert
_ORIG_TV_ITEM_I18N = ttk.Treeview.item
_ORIG_NB_ADD_I18N = ttk.Notebook.add
_ORIG_NB_INSERT_I18N = ttk.Notebook.insert
_ORIG_NB_TAB_I18N = ttk.Notebook.tab


_CB_FIXOS = ("Selecionar consulta", "Selecione")
_ORIG_CB_GET_I18N = ttk.Combobox.get
_ORIG_CB_SET_I18N = ttk.Combobox.set


def _cb_get_i18n(self):
    v = _ORIG_CB_GET_I18N(self)
    try: return self.__dict__.get("_cb_rev", {}).get(v, v)
    except Exception: return v


def _cb_set_i18n(self, value):
    if isinstance(value, str) and value in _CB_FIXOS:
        tr = _t(value)
        if tr != value: self.__dict__.setdefault("_cb_rev", {})[tr] = value
        value = tr
    return _ORIG_CB_SET_I18N(self, value)


def _cb_valores_i18n(self, d):
    v = d.get("values")
    if isinstance(v, (list, tuple)) and any(isinstance(x, str) and x in _CB_FIXOS for x in v):
        self.__dict__["_cb_vals_orig"] = list(v)
        rev = self.__dict__.setdefault("_cb_rev", {})
        novos = []
        for x in v:
            if isinstance(x, str) and x in _CB_FIXOS:
                tr = _t(x)
                if tr != x: rev[tr] = x
                novos.append(tr)
            else: novos.append(x)
        d = dict(d); d["values"] = novos
    return d


def _options_i18n(self, cnf, kw=None):
    if isinstance(self, ttk.Combobox):
        try:
            d = tk._cnfmerge((cnf, kw)) if kw else cnf
            if isinstance(d, dict) and "values" in d: cnf = _cb_valores_i18n(self, d); kw = None
        except Exception: pass
    if _I18N["ativo"] and not _I18N["pausa"]:
        try:
            d = tk._cnfmerge((cnf, kw)) if kw else cnf
            if isinstance(d, dict) and any(k in d for k in ("text", "label", "title")):
                d = dict(d); kw = None
                for k in ("text", "label", "title"):
                    v = d.get(k)
                    if isinstance(v, str) and v:
                        if k == "text" and _i18n_livre(self): self.__dict__.setdefault("_textos_orig", {})["text"] = v
                        if k != "text" or _i18n_livre(self): d[k] = _t(v)
                cnf = d
        except Exception: pass
    return _ORIG_OPTIONS_I18N(self, cnf, kw)


def _cget_i18n(self, key):
    v = _ORIG_CGET_I18N(self, key)
    if key == "text" and _I18N["ativo"]:
        try:
            o = self.__dict__.get("_textos_orig", {}).get("text")
            if o is not None and str(v) == _t(o): return o
        except Exception: pass
    return v


def _wm_title_i18n(self, string=None):
    if string is None:
        v = _ORIG_WM_TITLE_I18N(self)
        o = self.__dict__.get("_titulo_orig")
        if o is not None and _I18N["ativo"] and v == _t(o): return o
        return v
    self.__dict__["_titulo_orig"] = string
    return _ORIG_WM_TITLE_I18N(self, _t(string) if _I18N["ativo"] and not _I18N["pausa"] else string)


def _tv_heading_i18n(self, column, option=None, **kw):
    if isinstance(kw.get("text"), str) and _i18n_livre(self):
        self.__dict__.setdefault("_cab_orig", {})[column] = kw["text"]
        if _I18N["ativo"] and not _I18N["pausa"]: kw = dict(kw); kw["text"] = _t(kw["text"])
    return _ORIG_TV_HEADING_I18N(self, column, option, **kw)


def _tv_insert_i18n(self, parent, index, iid=None, **kw):
    traduzir = isinstance(kw.get("text"), str) and _i18n_livre(self)
    orig = kw.get("text")
    if traduzir and _I18N["ativo"] and not _I18N["pausa"]: kw = dict(kw); kw["text"] = _t(orig)
    item = _ORIG_TV_INSERT_I18N(self, parent, index, iid, **kw)
    if traduzir and orig and _t(orig) != orig:
        try: self.__dict__.setdefault("_itens_txt_orig", {})[item] = orig
        except Exception: pass
    return item


def _tv_item_i18n(self, item, option=None, **kw):
    if isinstance(kw.get("text"), str) and _i18n_livre(self):
        orig = kw["text"]
        reg = self.__dict__.setdefault("_itens_txt_orig", {})
        if _I18N["ativo"] and not _I18N["pausa"]:
            kw = dict(kw); kw["text"] = _t(orig)
        if kw["text"] != orig: reg[item] = orig
        else: reg.pop(item, None)
    return _ORIG_TV_ITEM_I18N(self, item, option, **kw)


def _nb_reg(self, child, kw):
    if isinstance(kw.get("text"), str):
        try: self.__dict__.setdefault("_abas_orig", {})[str(child)] = kw["text"]
        except Exception: pass
        if _I18N["ativo"] and not _I18N["pausa"]:
            kw = dict(kw); kw["text"] = _t(kw["text"])
    return kw


def _nb_add_i18n(self, child, **kw):
    return _ORIG_NB_ADD_I18N(self, child, **_nb_reg(self, child, kw))


def _nb_insert_i18n(self, pos, child, **kw):
    return _ORIG_NB_INSERT_I18N(self, pos, child, **_nb_reg(self, child, kw))


def _nb_tab_i18n(self, tab_id, option=None, **kw):
    if kw: kw = _nb_reg(self, tab_id, kw)
    return _ORIG_NB_TAB_I18N(self, tab_id, option, **kw)


