def _retraduzir(w):
    try: filhos = w.winfo_children()
    except Exception: filhos = []
    try:
        o = w.__dict__.get("_titulo_orig")
        if o is not None: w.title(o)
    except Exception: pass
    try:
        o = w.__dict__.get("_textos_orig", {}).get("text")
        if o is not None: w.configure(text=o)
    except Exception: pass
    if isinstance(w, ttk.Treeview):
        for col, txt in list(w.__dict__.get("_cab_orig", {}).items()):
            try: w.heading(col, text=txt)
            except Exception: pass
        for iid, txt in list(w.__dict__.get("_itens_txt_orig", {}).items()):
            try:
                if w.exists(iid): w.item(iid, text=txt)
            except Exception: pass
    if isinstance(w, ttk.Combobox) and "_cb_vals_orig" in w.__dict__:
        try:
            atual = w.get()
            w.configure(values=w.__dict__["_cb_vals_orig"])
            if atual in _CB_FIXOS: w.set(atual)
        except Exception: pass
    if isinstance(w, ttk.Notebook):
        for aba, txt in list(w.__dict__.get("_abas_orig", {}).items()):
            try: w.tab(aba, text=txt)
            except Exception: pass
    for f in filhos: _retraduzir(f)


def _idiomas_disponiveis(cfg=None):
    cfg = cfg or _ler_config_ini()
    lista = cfg.get("idioma", {}).get("idiomas") or list(_IDIOMAS_PADRAO)
    res = []
    for a in lista:
        c = os.path.join(PASTA_CONFIGS, a)
        if os.path.exists(c) and a.lower() not in {x.lower() for x, _ in res}: res.append((a, _nome_idioma(c)))
    return res


def _idioma_efetivo(cfg, prefs):
    disp = [a for a, _ in _idiomas_disponiveis(cfg)]
    if not disp: return ""
    por_nome = {a.lower(): a for a in disp}
    pref = str((prefs or {}).get("idioma") or "").strip()
    if pref and pref.lower() in por_nome: return por_nome[pref.lower()]
    pad = str(cfg.get("idioma", {}).get("idiomapadrao") or IDIOMA_PADRAO).strip()
    if pad.lower() in por_nome: return por_nome[pad.lower()]
    return ""


def _arquivo_por_idioma(caminho):
    cod = _I18N.get("codigo") or "PTBR"
    if not _I18N["ativo"] or cod == "PTBR": return caminho
    base, ext = os.path.splitext(caminho)
    alt = f"{base}_{cod}{ext}"
    return alt if os.path.exists(alt) else caminho


