def _norm_txt_ic(v):
    t = v.strip()
    while t and t[-1] in "….:": t = t[:-1].rstrip()
    return t.lower()


def _icone_espaco():
    im = _ICONES.get("espaco")
    if im is None:
        lado = 24
        folha = _folha_icones(_ICONES["modelo"], bool(_TEMA.get("escuro"))) if _ICONES["modelo"] else None
        if folha is not None and folha.width() >= ICONES_COLUNAS: lado = folha.width() // ICONES_COLUNAS
        try: im = tk.PhotoImage(width=1, height=lado)
        except Exception: return None
        _ICONES["espaco"] = im
    return im


def _icone_fixo(w, nome):
    try:
        w.__dict__["_ic_fixo"] = nome
        w.configure(text=w.cget("text"))
    except Exception: pass


def _eh_simbolo_ic(tok):
    t = tok.replace("\ufe0f", "").replace("\u200d", "")
    if not t: return False
    for ch in t:
        if ch in "ƒØℹ": continue
        if ord(ch) < 128 or unicodedata.category(ch) not in ("So", "Sm", "Sk"): return False
    return True


def _modelos_icones_achados():
    try:
        return sorted({f[:-len("_claro.png")] for f in os.listdir(PASTA_ICONES)
                       if f.lower().endswith("_claro.png") and len(f) > len("_claro.png")}, key=str.lower)
    except Exception:
        return []


def _modelos_icones_disponiveis(cfg=None):
    cfg = cfg or _ler_config_ini()
    achados = {m.lower(): m for m in _modelos_icones_achados()}
    lista = cfg.get("icones", {}).get("modelos") or list(_MODELOS_ICONES_PADRAO)
    res = [achados[m.lower()] for m in lista if m.lower() in achados]
    return res


def _modelo_icones_efetivo(cfg, prefs):
    disp = {m.lower(): m for m in _modelos_icones_disponiveis(cfg)}
    pref = str((prefs or {}).get("icones") or "").strip()
    if pref:
        if pref.lower() == "emoji": return ""
        if pref.lower() in disp: return disp[pref.lower()]
    pad = str(cfg.get("icones", {}).get("modelopadrao") or MODELO_ICONES_PADRAO).strip()
    if pad.lower() == "emoji": return ""
    return disp.get(pad.lower(), "")


def _definir_modelo_icones(modelo):
    _ICONES["modelo"] = modelo or ""


def _folha_icones(modelo, escuro):
    k = (modelo.lower(), escuro)
    if k in _ICONES["folhas"]: return _ICONES["folhas"][k]
    img = None
    for m in (("escuro", "claro") if escuro else ("claro", "escuro")):
        cam = os.path.join(PASTA_ICONES, f"{modelo}_{m}.png")
        if os.path.exists(cam):
            try: img = tk.PhotoImage(file=cam); break
            except Exception as ex: _log(f"Ícones ilegíveis {cam}: {ex}")
    _ICONES["folhas"][k] = img
    return img


def _icone(nome, secao="A", modelo=None, escuro=None):
    modelo = _ICONES["modelo"] if modelo is None else modelo
    if not modelo or nome not in ICONES_ORDEM: return None
    escuro = bool(_TEMA.get("escuro")) if escuro is None else escuro
    k = (modelo.lower(), escuro, nome, secao)
    if k in _ICONES["imgs"]: return _ICONES["imgs"][k]
    img = None
    folha = _folha_icones(modelo, escuro)
    if folha is not None:
        try:
            lado = folha.width() // ICONES_COLUNAS
            linhas = -(-len(ICONES_ORDEM) // ICONES_COLUNAS)
            i = ICONES_ORDEM.index(nome)
            mult = {"B": 1, "C": 2}.get(secao, 0)
            if mult and folha.height() < (mult + 1) * linhas * lado: mult = 0
            desl = mult * linhas
            x, y = (i % ICONES_COLUNAS) * lado, (desl + i // ICONES_COLUNAS) * lado
            if lado > 0 and y + lado <= folha.height():
                img = tk.PhotoImage(width=lado, height=lado)
                img.tk.call(img, "copy", folha, "-from", x, y, x + lado, y + lado, "-to", 0, 0)
        except Exception as ex:
            _log(f"Ícone {nome}: {ex}"); img = None
    _ICONES["imgs"][k] = img
    return img


def _icone_alerta(tipo):
    modelo = _ICONES["modelo"]
    if not modelo or tipo not in ICONES_ALERTAS: return None
    k = (modelo.lower(), tipo)
    if k in _ICONES["alertas"]: return _ICONES["alertas"][k]
    img = None
    cam = os.path.join(PASTA_ICONES, f"{modelo}_alertas.png")
    if os.path.exists(cam):
        try:
            folha = _ICONES["folhas"].get((modelo.lower(), "alertas"))
            if folha is None:
                folha = tk.PhotoImage(file=cam); _ICONES["folhas"][(modelo.lower(), "alertas")] = folha
            lado = folha.height(); i = ICONES_ALERTAS.index(tipo)
            if (i + 1) * lado <= folha.width():
                img = tk.PhotoImage(width=lado, height=lado)
                img.tk.call(img, "copy", folha, "-from", i * lado, 0, (i + 1) * lado, lado, "-to", 0, 0)
        except Exception as ex:
            _log(f"Alerta {tipo}: {ex}"); img = None
    _ICONES["alertas"][k] = img
    return img


def _secao_cor(w, cor):
    try:
        r, g, b = (v / 65535 for v in w.winfo_rgb(cor))
        if (0.2126 * r + 0.7152 * g + 0.0722 * b) < 0.62: return "B"
        mx, mn = max(r, g, b), min(r, g, b)
        return "C" if mx > 0 and (mx - mn) / mx > 0.35 else "A"
    except Exception:
        return "B" if _TEMA.get("escuro") else "A"


def _secao_widget(w):
    try: return _secao_cor(w, w.tk.call(w._w, "cget", "-background"))
    except Exception: return "B" if _TEMA.get("escuro") else "A"


def _icone_em_botao(btn, nome, texto=None):
    try: d = btn.__dict__.get("_ic")
    except Exception: return
    if d is None:
        try: d = {"w": btn.cget("width"), "h": btn.cget("height"), "texto": btn.cget("text")}
        except Exception: return
        btn.__dict__.pop("_ic_auto", None)
        wch = btn.__dict__.pop("_ic_wch", None)
        if wch: d["w"] = wch
        btn.__dict__["_ic"] = d
        _ICONES["botoes"].append(btn)
    d["nome"] = nome
    if texto is not None: d["texto"] = texto
    img = _icone(nome, _secao_widget(btn))
    try:
        if img is not None:
            btn.config(image=img, text="", compound="center", width=img.width() + 10, height=img.height() + 2)
        else:
            btn.config(image="", text=d["texto"], width=d["w"], height=d["h"])
    except Exception: pass


def _ic_aplicar_imagem(w):
    if "_ic" in w.__dict__: return
    nome = w.__dict__.get("_ic_auto")
    try:
        img = None
        if nome == "_espaco": img = _icone_espaco()
        elif nome: img = _icone(nome, _secao_widget(w))
        if img is not None:
            ttkw = isinstance(w, ttk.Widget)
            if "_ic_wch" not in w.__dict__:
                wch = None
                if not ttkw:
                    try: wch = int(str(w.tk.call(w._w, "cget", "-width")) or 0)
                    except Exception: wch = 0
                w.__dict__["_ic_wch"] = wch
            wch = w.__dict__["_ic_wch"]
            comp = w.__dict__.get("_ic_comp", "left")
            if not ttkw and wch:
                try:
                    f = tkfont.Font(font=w.tk.call(w._w, "cget", "-font"))
                    txt = str(w.tk.call(w._w, "cget", "-text"))
                    if comp == "center" or not txt.strip(): px = img.width() + 12
                    else: px = max(wch * f.measure("0") + 4, f.measure(txt) + img.width() + 18)
                    w.tk.call(w._w, "configure", "-width", px)
                except Exception: pass
            w.tk.call(w._w, "configure", "-image", img, "-compound", comp)
            return
        if "_ic_wch" in w.__dict__:
            wch = w.__dict__.pop("_ic_wch")
            if wch is None: w.tk.call(w._w, "configure", "-image", "")
            else: w.tk.call(w._w, "configure", "-image", "", "-width", wch)
    except Exception:
        pass


_CLASSES_IC = (tk.Button, tk.Label, tk.Checkbutton, tk.Radiobutton, ttk.Button, ttk.Label)


def _ic_cnf(self, d):
    if not isinstance(d, dict) or "text" not in d or "_ic" in self.__dict__: return d
    if not isinstance(self, _CLASSES_IC): return d
    v = d.get("text")
    if not isinstance(v, str): return d
    if d.get("image") not in (None, "") and not self.__dict__.get("_ic_auto"): return d
    if "image" not in d and "_ic_auto" not in self.__dict__:
        try:
            if str(self.tk.call(self._w, "cget", "-image")): return d
        except Exception: pass
    self.__dict__["_ic_txt_orig"] = v
    nome = None; exib = v; comp = "left"
    modelo = _ICONES["modelo"]
    botao = isinstance(self, (tk.Button, ttk.Button))
    m = _RE_IC_PREFIXO.match(v)
    fixo = self.__dict__.get("_ic_fixo")
    if m and modelo and _eh_simbolo_ic(m.group(1)):
        tok = m.group(1).replace("\ufe0f", "")
        cand = fixo or _EMOJI_ICONE.get(tok)
        if cand and _icone(cand) is not None:
            nome = cand; exib = " " + m.group(3)
        else:
            exib = m.group(3)
    elif fixo and modelo and _icone(fixo) is not None:
        nome = fixo; exib = " " + v
    elif modelo and botao and v.strip():
        so = v.strip().replace("\ufe0f", "")
        ms = _RE_IC_SUFIXO.match(v)
        cand = _SOZINHO_ICONE.get(so) or (_EMOJI_ICONE.get(so) if _eh_simbolo_ic(so) else None)
        if cand and _icone(cand) is not None:
            nome = cand; exib = ""; comp = "center"
        elif ms and _eh_simbolo_ic(ms.group(2)):
            tok = ms.group(2).replace("\ufe0f", "")
            cand = _SUFIXO_ICONE.get(tok) or _EMOJI_ICONE.get(tok)
            if cand and _icone(cand) is not None:
                nome = cand; exib = ms.group(1) + " "; comp = "right"
            else:
                exib = ms.group(1)
        else:
            base = v
            try:
                o = self.__dict__.get("_textos_orig", {}).get("text")
                if isinstance(o, str) and o != v and _t(o) == v: base = o
            except Exception: pass
            cand = _TEXTO_ICONE.get(_norm_txt_ic(base))
            if cand and _icone(cand) is not None:
                nome = cand; exib = " " + v
            elif isinstance(self, tk.Button):
                alt = d.get("height")
                if alt in (None, "", 0, "0") and not d.get("bitmap"): nome = "_espaco"
    d = dict(d); d["text"] = exib
    self.__dict__["_ic_auto"] = nome
    self.__dict__["_ic_exib"] = exib
    self.__dict__["_ic_comp"] = comp
    return d


def _ic_menu(self, d):
    if not isinstance(d, dict) or not isinstance(d.get("label"), str) or not _ICONES["modelo"]: return d
    m = _RE_IC_PREFIXO.match(d["label"])
    if m and _eh_simbolo_ic(m.group(1)):
        d = dict(d); d["label"] = m.group(3)
        nome = _EMOJI_ICONE.get(m.group(1).replace("️", ""))
        img = _icone(nome, _secao_widget(self)) if nome else None
        if img is not None and "image" not in d: d["image"] = img; d["compound"] = "left"
    return d


