def _options_icones(self, cnf, kw=None):
    try:
        if isinstance(self, _CLASSES_IC) or isinstance(self, tk.Menu):
            d = tk._cnfmerge((cnf, kw)) if kw else cnf
            if isinstance(d, dict):
                d2 = _ic_menu(self, d) if isinstance(self, tk.Menu) else _ic_cnf(self, d)
                if d2 is not d: cnf, kw = d2, None
    except Exception: pass
    return _ORIG_OPTIONS_ICONES(self, cnf, kw)


_ORIG_OPTIONS_I18N = _options_icones
_ORIG_BW_INIT_IC = tk.BaseWidget.__init__
_ORIG_CONFIGURE_IC = tk.Misc._configure
_ORIG_CGET_IC = tk.Misc.cget


def _bw_init_ic(self, *a, **k):
    _ORIG_BW_INIT_IC(self, *a, **k)
    if "_ic_auto" in self.__dict__ or "_ic_wch" in self.__dict__: _ic_aplicar_imagem(self)


def _configure_ic(self, cmd, cnf, kw):
    r = _ORIG_CONFIGURE_IC(self, cmd, cnf, kw)
    try:
        if cmd == "configure" and ("_ic_auto" in self.__dict__ or "_ic_wch" in self.__dict__) and (cnf or kw):
            _ic_aplicar_imagem(self)
        elif cmd == "configure" and "_ic" in self.__dict__ and _ICONES["modelo"]:
            ch = set(kw or ()) | (set(cnf) if isinstance(cnf, dict) else set())
            if ch & {"bg", "background"}:
                d = self.__dict__["_ic"]; _icone_em_botao(self, d.get("nome"))
    except Exception: pass
    return r


def _cget_ic(self, key):
    v = _ORIG_CGET_IC(self, key)
    if key == "text":
        try:
            ex = self.__dict__.get("_ic_exib")
            if ex is not None and str(v) == ex:
                o = self.__dict__.get("_textos_orig", {}).get("text")
                return o if o is not None else self.__dict__.get("_ic_txt_orig", v)
        except Exception: pass
    return v


tk.BaseWidget.__init__ = _bw_init_ic
tk.Misc._configure = _configure_ic
tk.Misc.cget = _cget_ic
tk.Misc.__getitem__ = _cget_ic

