def _wm_title_ic(self, string=None):
    if string is not None and _ICONES["modelo"] and isinstance(string, str):
        m = _RE_IC_PREFIXO.match(string)
        if m and _eh_simbolo_ic(m.group(1)): string = m.group(3)
    return _ORIG_WM_TITLE_IC(self, string) if string is not None else _ORIG_WM_TITLE_IC(self)


