def _reaplicar_icones(raiz=None):
    raiz = raiz or _TEMA.get("root") or tk._default_root
    if raiz is None: return

    def _andar(w):
        try: filhos = w.winfo_children()
        except Exception: filhos = []
        try:
            dd = w.__dict__
            if "_ic" in dd: _icone_em_botao(w, dd["_ic"]["nome"])
            elif "_ic_txt_orig" in dd:
                o = dd.get("_textos_orig", {}).get("text", dd["_ic_txt_orig"])
                w.configure(text=o)
            o_t = dd.get("_titulo_orig")
            if o_t is not None: w.title(o_t)
        except Exception: pass
        for f in filhos: _andar(f)
    _andar(raiz)
    _ICONES["botoes"] = [b for b in _ICONES["botoes"] if _vivo(b)]


def _vivo(w):
    try: return bool(w.winfo_exists())
    except Exception: return False


