def _caminho_paleta(arquivo):
    if not arquivo: arquivo = PALETA_PADRAO
    c = arquivo if os.path.isabs(arquivo) else os.path.join(PASTA_CONFIGS, arquivo)
    if not os.path.exists(c) and not c.lower().endswith(".cor") and os.path.exists(c + ".cor"): c += ".cor"
    return c


def _ler_paleta(arquivo):
    c = _caminho_paleta(arquivo)
    try: mt = os.path.getmtime(c)
    except Exception: mt = None
    if (c, mt) in _CACHE_PALETAS: return _CACHE_PALETAS[(c, mt)]
    res = {"nome": os.path.splitext(os.path.basename(c))[0], "cores": {}, "arquivo": c, "existe": mt is not None}
    if mt is not None:
        def rgb(p):
            n = [int(x) for x in re.findall(r"\d+", p)][:3]
            return "#%02x%02x%02x" % tuple(max(0, min(255, x)) for x in n) if len(n) == 3 else None
        try:
            with open(c, "r", encoding="utf-8-sig", errors="replace") as f: linhas = f.read().splitlines()
            secao = None; primeira = True
            for l in linhas:
                s = l.strip()
                if not s or s.startswith("#"): continue
                if primeira and not s.startswith("["):
                    res["nome"] = s; primeira = False; continue
                primeira = False
                if s.startswith("[") and "]" in s:
                    secao = s[1:s.index("]")].strip().lower(); continue
                if "=" in s and secao:
                    k, v = s.split("=", 1)
                    partes = v.split("#", 1)[0].split(";")
                    claro = rgb(partes[0]); escuro = rgb(partes[1]) if len(partes) > 1 else None
                    if claro: res["cores"][f"{secao}.{k.strip().lower()}"] = (claro, escuro or claro)
        except Exception as ex:
            _log(f"Paleta ilegível {c}: {ex}")
    _CACHE_PALETAS[(c, mt)] = res
    return res


def _sistema_escuro():
    if sys.platform.startswith("win"):
        try:
            import winreg
            k = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                               r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")
            v, _ = winreg.QueryValueEx(k, "AppsUseLightTheme")
            return int(v) == 0
        except Exception: return False
    return False


def _definir_tema(arquivo, modo):
    pal = _ler_paleta(arquivo)
    modo = modo if modo in MODOS_COR else "claro"
    escuro = modo == "escuro" or (modo == "sistema" and _sistema_escuro())
    identidade = not escuro and all(
        pal["cores"].get(f"{s}.{k}", (origs[0],))[0] == origs[0] for s, k, _t, origs in _PAPEIS_COR)
    if not pal["existe"] and not escuro: identidade = True
    _TEMA.update({"paleta": pal["cores"], "nome": pal["nome"], "arquivo": os.path.basename(pal["arquivo"]),
                  "modo": modo, "escuro": escuro, "identidade": identidade})


def _retematizar(w):
    pilha = [w]
    while pilha:
        x = pilha.pop()
        try: pilha.extend(x.winfo_children())
        except Exception: pass
        if isinstance(x, ttk.Widget):
            for tag, d in (x.__dict__.get("_ttags_orig") or {}).items():
                for op, v in d.items():
                    try: x.tk.call(x._w, "tag", "configure", tag, "-" + op, _traduzir_cor(_tipo_opcao(op), v))
                    except Exception: pass
            continue
        _tematizar_widget(x)
        lreg = x.__dict__.get("_litens_orig")
        if lreg:
            try: n_lb = int(x.size())
            except Exception: n_lb = 0
            for idx, d in list(lreg.items()):
                if idx >= n_lb: lreg.pop(idx, None); continue
                for op, v in d.items():
                    try: x.tk.call(x._w, "itemconfigure", idx, "-" + op, _traduzir_cor(_tipo_opcao(op), v))
                    except Exception: pass
        reg = x.__dict__.get("_itens_orig")
        if reg:
            for item, (tipo, cores) in list(reg.items()):
                try:
                    if not x.type(item): reg.pop(item, None); continue
                    for op, v in cores.items():
                        k = "t" if (op.endswith("outline") or (tipo == "text" and op.endswith("fill"))) else "f"
                        x.tk.call(x._w, "itemconfigure", item, "-" + op, _traduzir_cor(k, v))
                except Exception: pass
        for tag, d in (x.__dict__.get("_tags_orig") or {}).items():
            for op, v in d.items():
                try: x.tk.call(x._w, "tag", "configure", tag, "-" + op, _traduzir_cor(_tipo_opcao(op), v))
                except Exception: pass
        try:
            if "image" in x.keys():
                nome = str(x.cget("image"))
                if nome in _IMAGENS_REG:
                    p, h, bg = _IMAGENS_REG[nome]
                    novo = carregar_imagem_com_fundo(p, h, bg)
                    if novo is not None:
                        x.tk.call(x._w, "configure", "-image", novo); x._img_tema = novo
        except Exception: pass


def _aplicar_estilos_ttk(root):
    try: st = ttk.Style(root)
    except Exception: return
    if _TEMA["base_ttk"] is None:
        try: _TEMA["base_ttk"] = st.theme_use()
        except Exception: _TEMA["base_ttk"] = "default"
    C = lambda v: _traduzir_cor("f", v)
    T = lambda v: _traduzir_cor("t", v)
    try:
        if _TEMA["identidade"]:
            if st.theme_use() != _TEMA["base_ttk"]: st.theme_use(_TEMA["base_ttk"])
            try:
                st.configure("TNotebook.Tab", padding=[14, 5], font=("Arial", 10))
                st.map("TNotebook.Tab", font=[("selected", ("Arial", 10, "bold"))],
                       foreground=[("selected", "#0D47A1")], expand=[("selected", [2, 3, 2, 0])])
            except Exception: pass
            for op, v in (("background", "#ffffff"), ("foreground", "#000000"),
                          ("selectBackground", "#1976d2"), ("selectForeground", "#ffffff")):
                root.option_add(f"*TCombobox*Listbox.{op}", v, 80)
            return
        if st.theme_use() != "clam": st.theme_use("clam")
        fundo, campo, txt = C("#f5f5f5"), C("#ffffff"), T("#000000")
        div, icone, sel, sel_txt = C("#dddddd"), C("#e0e0e0"), C("#1976d2"), T("#ffffff")
        st.configure(".", background=fundo, foreground=txt, fieldbackground=campo, bordercolor=div,
                     lightcolor=fundo, darkcolor=div, troughcolor=fundo, selectbackground=sel,
                     selectforeground=sel_txt, insertcolor=txt, arrowcolor=txt)
        st.map(".", background=[("active", icone), ("disabled", fundo)], foreground=[("disabled", T("#9e9e9e"))])
        st.configure("Treeview", background=campo, fieldbackground=campo, foreground=txt, bordercolor=div)
        st.map("Treeview", background=[("selected", sel)], foreground=[("selected", sel_txt)])
        st.configure("Treeview.Heading", background=C("#dce7f1"), foreground=txt, bordercolor=div)
        st.map("Treeview.Heading", background=[("active", C("#bbdefb"))])
        st.configure("TCombobox", fieldbackground=campo, background=icone, foreground=txt, arrowcolor=txt)
        st.map("TCombobox", fieldbackground=[("readonly", campo), ("disabled", fundo)],
               foreground=[("readonly", txt), ("disabled", T("#9e9e9e"))],
               selectbackground=[("readonly", campo)], selectforeground=[("readonly", txt)])
        st.configure("TEntry", fieldbackground=campo, foreground=txt)
        st.configure("TSpinbox", fieldbackground=campo, foreground=txt, arrowcolor=txt)
        st.configure("TNotebook", background=fundo, bordercolor=div)
        st.configure("TNotebook.Tab", background=icone, foreground=txt, bordercolor=div, padding=[14, 5],
                     font=("Arial", 10))
        st.map("TNotebook.Tab", background=[("selected", sel), ("active", C("#bbdefb"))],
               foreground=[("selected", sel_txt)], font=[("selected", ("Arial", 10, "bold"))],
               expand=[("selected", [2, 3, 2, 0])])
        st.configure("TScrollbar", background=icone, troughcolor=fundo, arrowcolor=txt, bordercolor=div)
        st.configure("TProgressbar", background=sel, troughcolor=campo)
        for est in ("TFrame", "TLabel", "TCheckbutton", "TRadiobutton", "TLabelframe", "TLabelframe.Label"):
            st.configure(est, background=fundo, foreground=txt)
        st.configure("TButton", background=icone, foreground=txt)
        for op, v in (("background", campo), ("foreground", txt), ("selectBackground", sel), ("selectForeground", sel_txt)):
            root.option_add(f"*TCombobox*Listbox.{op}", v, 80)
    except Exception as ex:
        _log(f"Estilos ttk: {ex}")


def _ocultar_pasta(caminho):
    if not sys.platform.startswith("win") or not caminho or not os.path.isdir(caminho): return
    try:
        import ctypes
        atual = ctypes.windll.kernel32.GetFileAttributesW(caminho)
        if atual != -1 and not (atual & 0x02):
            ctypes.windll.kernel32.SetFileAttributesW(caminho, atual | 0x02)
    except Exception: pass


def _ini_definir(texto, secao, chave, valor, comentario=""):
    linhas = texto.replace("\r\n", "\n").split("\n")
    alvo = secao.lower(); atual = None; ini_sec = None; fim_sec = None
    for i, l in enumerate(linhas):
        s = l.strip()
        if s.startswith("[") and "]" in s:
            if atual == alvo and fim_sec is None: fim_sec = i
            atual = s[1:s.index("]")].strip().lower()
            if atual == alvo: ini_sec = i; fim_sec = None
            continue
        if atual == alvo and "=" in s and not s.startswith((";", "#")):
            k = s.split("=", 1)[0].strip()
            if k.lower() == chave.lower():
                resto = l.split("=", 1)[1]
                com = resto[resto.index("#"):].strip() if "#" in resto else (f"# {comentario}" if comentario else "")
                base = f"{k} = {valor}"
                linhas[i] = (base.ljust(21) + " " if len(base) < 21 else base + "    ") + com if com else base
                return "\n".join(linhas)
    base = f"{chave} = {valor}"
    nova = ((base.ljust(21) + " " if len(base) < 21 else base + "    ") + f"# {comentario}") if comentario else base
    if ini_sec is None:
        while linhas and not linhas[-1].strip(): linhas.pop()
        linhas += ["", f"[{secao}]", nova, ""]
    else:
        j = fim_sec if fim_sec is not None else len(linhas)
        while j - 1 > ini_sec and not linhas[j - 1].strip(): j -= 1
        linhas.insert(j, nova)
    return "\n".join(linhas)


_LOG_MEMORIA = collections.deque(maxlen=3000)


class _TravaConsultas:
    def __init__(self, caminho, espera=15):
        self.trava = caminho + ".lock"; self.espera = espera; self.ok = False

    def __enter__(self):
        t0 = time.time()
        while True:
            try:
                fd = os.open(self.trava, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                try: os.write(fd, f"{_usuario_atual()} {datetime.now().isoformat()}".encode("utf-8"))
                finally: os.close(fd)
                self.ok = True; return self
            except FileExistsError:
                try:
                    if time.time() - os.path.getmtime(self.trava) > 60:
                        os.remove(self.trava); continue
                except Exception: pass
                if time.time() - t0 > self.espera:
                    raise RuntimeError("As consultas salvas estão sendo gravadas por outro usuário neste momento. "
                                       "Tente de novo em alguns segundos.")
                time.sleep(0.2)
            except Exception:
                self.ok = False; return self

    def __exit__(self, *a):
        if self.ok:
            try: os.remove(self.trava)
            except Exception: pass
        return False


PASTA_BACKUP_CONSULTAS = os.path.join(PASTA_CONFIGS, ".backups_consultas")


def _backup_consultas(forcar=False, manter=40):
    if not os.path.exists(LOG_FILE): return
    try:
        os.makedirs(PASTA_BACKUP_CONSULTAS, exist_ok=True)
        _ocultar_pasta(PASTA_BACKUP_CONSULTAS)
        existentes = sorted(f for f in os.listdir(PASTA_BACKUP_CONSULTAS) if f.lower().endswith(".log"))
        if not forcar and existentes:
            ultimo = os.path.join(PASTA_BACKUP_CONSULTAS, existentes[-1])
            if time.time() - os.path.getmtime(ultimo) < 6 * 3600: return
        nome = f"TabWon_logs_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')[:-3]}_{_usuario_atual()}.log"
        shutil.copy2(LOG_FILE, os.path.join(PASTA_BACKUP_CONSULTAS, nome))
        existentes = sorted(f for f in os.listdir(PASTA_BACKUP_CONSULTAS) if f.lower().endswith(".log"))
        for f in existentes[:-manter]:
            try: os.remove(os.path.join(PASTA_BACKUP_CONSULTAS, f))
            except Exception: pass
    except Exception as ex:
        _log(f"Backup das consultas: {ex}")


def _ler_blocos_consultas():
    if not os.path.exists(LOG_FILE): return []
    with open(LOG_FILE, "r", encoding="utf-8") as f: conteudo = f.read()
    return [b.strip() for b in re.split(r'\n------\s*\n', conteudo) if b.strip()]


def _anexar_consultas(texto):
    with _TravaConsultas(LOG_FILE):
        _backup_consultas()
        with open(LOG_FILE, "a", encoding="utf-8") as f: f.write(texto)


