def _pasta_downloads():
    if os.name == "nt":
        try:
            import ctypes, uuid
            guid = (ctypes.c_ubyte * 16).from_buffer_copy(uuid.UUID("374DE290-123F-4565-9164-39C4925E467B").bytes_le)
            ptr = ctypes.c_wchar_p()
            if ctypes.windll.shell32.SHGetKnownFolderPath(ctypes.byref(guid), 0, None, ctypes.byref(ptr)) == 0:
                caminho = ptr.value
                ctypes.windll.ole32.CoTaskMemFree(ptr)
                if caminho and os.path.isdir(caminho): return caminho
        except Exception: pass
    for c in (os.path.join(os.path.expanduser("~"), "Downloads"), os.path.expanduser("~")):
        if os.path.isdir(c): return c
    return os.path.expanduser("~")


def _formas_caminho(caminho):
    formas = set()
    for f in (os.path.abspath, os.path.realpath):
        try: formas.add(os.path.normcase(f(caminho)).rstrip("\\/"))
        except Exception: pass
    return {x for x in formas if x}


def _caminho_dentro(caminho, pasta):
    for c in _formas_caminho(caminho):
        for p in _formas_caminho(pasta):
            if c == p or c.startswith(p + os.sep): return True
    return False


def _usuario_atual():
    nome = os.environ.get("USERNAME") or os.environ.get("USER") or ""
    if not nome:
        try:
            import getpass; nome = getpass.getuser()
        except Exception: nome = "usuario"
    return re.sub(r"[^\w.-]", "_", nome) or "usuario"


def _arquivo_prefs():
    return os.path.join(PASTA_USUARIOS, f"{_usuario_atual()}.ini")

def _caminho_pasta_tabwin(valor):
    p = (valor or "").strip().strip('"').strip()
    if not p: return PASTA_SCRIPT
    if not (os.path.isabs(p) or os.path.splitdrive(p)[0]): p = os.path.join(PASTA_SCRIPT, p)
    return os.path.normpath(os.path.abspath(p))


def _definir_pasta_tabwin(valor):
    global PASTA_TABWIN, PASTA_DADOS, LOG_FILE, PASTA_USUARIOS, PASTA_BACKUP_CONSULTAS, SQL_LOG_FILE
    PASTA_TABWIN = _caminho_pasta_tabwin(valor)
    PASTA_DADOS = (PASTA_CONFIGS if os.path.normcase(PASTA_TABWIN) == os.path.normcase(PASTA_SCRIPT)
                   else os.path.join(PASTA_TABWIN, "TabWon_configs"))
    LOG_FILE = os.path.join(PASTA_DADOS, "TabWon_logs.log")
    PASTA_USUARIOS = os.path.join(PASTA_DADOS, ".usuarios")
    PASTA_BACKUP_CONSULTAS = os.path.join(PASTA_DADOS, ".backups_consultas")
    SQL_LOG_FILE = os.path.join(PASTA_DADOS, "TabWon_logs_sql.log")
    try: os.makedirs(PASTA_DADOS, exist_ok=True)
    except Exception: pass
    _log(f"Pasta do TabWin: {PASTA_TABWIN}")
    return PASTA_TABWIN


def _contar_defs(pasta):
    try: return sum(1 for f in os.listdir(pasta) if f.lower().endswith(".def"))
    except Exception: return -1


def _pasta_gravavel(pasta):
    try:
        os.makedirs(pasta, exist_ok=True)
        teste = os.path.join(pasta, f".tabwon_teste_{os.getpid()}.tmp")
        with open(teste, "w", encoding="utf-8") as f: f.write("ok")
        os.remove(teste)
        return True
    except Exception:
        return False


def _gravar_pasta_tabwin_ini(valor):
    try:
        with open(CONFIG_INI, "r", encoding="utf-8-sig") as f: texto = f.read()
    except Exception: texto = _INI_PADRAO
    texto = _ini_definir(texto, "pastas", "tabwin", valor,
                         "Pasta do TabWin: DEFs, CNVs, consultas salvas e preferências dos usuários; vazio = pasta do TabWon")
    tmp = CONFIG_INI + ".tmp_tabwon"
    with open(tmp, "w", encoding="utf-8", newline="\r\n") as f: f.write(texto.replace("\r\n", "\n"))
    os.replace(tmp, CONFIG_INI)


def _ler_config_ini():
    cfg = {"menu": {"editores": True, "consultorsql": True, "conversor": True},
           "consultas": {"renomear": True, "excluir": True},
           "cores": {"paletas": list(_PALETAS_PADRAO), "corpadrao": PALETA_PADRAO, "modopadrao": "claro"},
           "organizacao": {"identificadores": []},
           "idioma": {"idiomas": list(_IDIOMAS_PADRAO), "idiomapadrao": IDIOMA_PADRAO},
           "icones": {"modelos": list(_MODELOS_ICONES_PADRAO), "modelopadrao": MODELO_ICONES_PADRAO},
           "pastas": {"tabwin": ""}, "exportacao": {"pastatabwon": False}}
    if not os.path.exists(CONFIG_INI):
        try:
            os.makedirs(PASTA_CONFIGS, exist_ok=True)
            with open(CONFIG_INI, "w", encoding="utf-8", newline="\r\n") as f: f.write(_INI_PADRAO)
        except Exception: pass
    import configparser
    cp = configparser.ConfigParser(inline_comment_prefixes=("#",), strict=False, interpolation=None)
    try: cp.read(CONFIG_INI, encoding="utf-8-sig")
    except Exception as ex:
        _log(f"INI ilegível: {ex}"); return cfg
    def bol(sec, k, padrao):
        v = cp.get(sec, k, fallback="").strip().lower()
        if v == "": return padrao
        return v not in ("0", "false", "nao", "não", "n", "off")
    cfg["menu"]["editores"] = bol("menu", "editores", True)
    cfg["menu"]["consultorsql"] = bol("menu", "consultorsql", True)
    cfg["menu"]["conversor"] = bol("menu", "conversor", True)
    if cp.has_section("menu") and not cp.has_option("menu", "conversor"):
        try:
            with open(CONFIG_INI, "r", encoding="utf-8-sig") as f: texto_ini = f.read()
            novo_ini, n_sub = re.subn(r"(?im)^(\s*consultorsql\s*=.*)$",
                                      lambda m_: m_.group(1) + "\nconversor = 1         "
                                                                "# 1|0 exibe ou oculta no menu o conversor DBF ⟺ DBC",
                                      texto_ini, count=1)
            if n_sub:
                with open(CONFIG_INI, "w", encoding="utf-8", newline="\r\n") as f: f.write(novo_ini.replace("\r\n", "\n"))
        except Exception: pass
    cfg["consultas"]["renomear"] = bol("consultas", "renomear", True)
    cfg["consultas"]["excluir"] = bol("consultas", "excluir", True)
    pals = []
    for p in cp.get("cores", "paletas", fallback="").split(";"):
        p = p.strip()
        if not p: continue
        if not os.path.splitext(p)[1]: p += ".cor"
        pals.append(p)
    if pals: cfg["cores"]["paletas"] = pals
    cp_pad = cp.get("cores", "corpadrao", fallback="").strip()
    if cp_pad:
        if not os.path.splitext(cp_pad)[1]: cp_pad += ".cor"
        cfg["cores"]["corpadrao"] = cp_pad
    vistos_id = []
    for p in cp.get("organizacao", "logs_identificador", fallback="").split(";"):
        p = " ".join(p.split())
        if p and p not in vistos_id: vistos_id.append(p)
    cfg["organizacao"]["identificadores"] = vistos_id
    cfg["cores"]["modopadrao"] = {"1": "claro", "0": "escuro", "2": "sistema"}.get(
        cp.get("cores", "modopadrao", fallback="1").strip(), "claro")
    idis = []
    for p in re.split(r"[;,]", cp.get("idioma", "idiomas", fallback="")):
        p = p.strip()
        if not p: continue
        if not os.path.splitext(p)[1]: p += ".lng"
        if p.lower() not in {x.lower() for x in idis}: idis.append(p)
    if idis: cfg["idioma"]["idiomas"] = idis
    pad_i = cp.get("idioma", "idiomapadrao", fallback="").strip()
    if pad_i:
        if not os.path.splitext(pad_i)[1]: pad_i += ".lng"
        cfg["idioma"]["idiomapadrao"] = pad_i
    mods_ic = []
    for p in re.split(r"[;,]", cp.get("icones", "modelos", fallback="")):
        p = os.path.splitext(p.strip())[0]
        if p and p.lower() not in {x.lower() for x in mods_ic}: mods_ic.append(p)
    if {m.lower() for m in mods_ic} == {"linear", "solido", "circular", "arredondado", "duotone"}:
        mods_ic = list(_MODELOS_ICONES_PADRAO)
        if os.path.exists(CONFIG_INI):
            try:
                with open(CONFIG_INI, "r", encoding="utf-8-sig") as f: texto_ini = f.read()
                texto_ini = _ini_definir(texto_ini, "icones", "modelos", ";".join(_MODELOS_ICONES_PADRAO),
                                         "Modelos de ícones na pasta TabWon_configs/icones")
                with open(CONFIG_INI, "w", encoding="utf-8", newline="\r\n") as f: f.write(texto_ini.replace("\r\n", "\n"))
            except Exception: pass
    if mods_ic: cfg["icones"]["modelos"] = mods_ic
    pad_ic = cp.get("icones", "modelopadrao", fallback="").strip()
    if pad_ic: cfg["icones"]["modelopadrao"] = pad_ic
    cfg["pastas"]["tabwin"] = cp.get("pastas", "tabwin", fallback="").strip().strip('"').strip()
    cfg["exportacao"]["pastatabwon"] = bol("exportacao", "pastatabwon", False)
    faltam_secoes = [s for s in ("pastas", "exportacao") if not cp.has_section(s)]
    if faltam_secoes and os.path.exists(CONFIG_INI):
        try:
            with open(CONFIG_INI, "r", encoding="utf-8-sig") as f: texto_ini = f.read()
            if "pastas" in faltam_secoes:
                texto_ini = _ini_definir(texto_ini, "pastas", "tabwin", "",
                                         "Pasta do TabWin: DEFs, CNVs, consultas salvas e preferências dos usuários; vazio = pasta do TabWon")
            if "exportacao" in faltam_secoes:
                texto_ini = _ini_definir(texto_ini, "exportacao", "pastatabwon", "0",
                                         "1|0 permite salvar XLSX e CSV na pasta do TabWon e na pasta do TabWin (e subpastas); 0 = não permite")
            with open(CONFIG_INI, "w", encoding="utf-8", newline="\r\n") as f: f.write(texto_ini.replace("\r\n", "\n"))
        except Exception: pass
    if not cp.has_section("icones") and os.path.exists(CONFIG_INI):
        try:
            with open(CONFIG_INI, "r", encoding="utf-8-sig") as f: texto_ini = f.read()
            texto_ini = _ini_definir(texto_ini, "icones", "modelos", ";".join(_MODELOS_ICONES_PADRAO),
                                     "Modelos de ícones na pasta TabWon_configs/icones")
            texto_ini = _ini_definir(texto_ini, "icones", "modelopadrao", MODELO_ICONES_PADRAO,
                                     "Modelo padrão dos ícones; Emoji usa os símbolos de texto")
            with open(CONFIG_INI, "w", encoding="utf-8", newline="\r\n") as f: f.write(texto_ini.replace("\r\n", "\n"))
        except Exception: pass
    if not cp.has_section("idioma") and os.path.exists(CONFIG_INI):
        try:
            with open(CONFIG_INI, "r", encoding="utf-8-sig") as f: texto_ini = f.read()
            texto_ini = _ini_definir(texto_ini, "idioma", "idiomas", ",".join(_IDIOMAS_PADRAO),
                                     "Lista de idiomas disponíveis")
            texto_ini = _ini_definir(texto_ini, "idioma", "idiomapadrao", IDIOMA_PADRAO,
                                     "PTBR = Português (Brasil), ENUS = Inglês (EUA), ESES = Espanhol (América Latina)")
            with open(CONFIG_INI, "w", encoding="utf-8", newline="\r\n") as f: f.write(texto_ini.replace("\r\n", "\n"))
        except Exception: pass
    return cfg


