def _saudacao_por_horario(agora=None):
    agora = agora or datetime.now()
    m = agora.hour * 60 + agora.minute
    if m <= 12 * 60: return "Bom dia"
    if m <= 18 * 60: return "Boa tarde"
    return "Boa noite"


def _limpar_nome_usuario(nome):
    return " ".join(str(nome or "").replace("\r", " ").replace("\n", " ").split())[:50]


def _ler_prefs_usuario():
    p = _arquivo_prefs(); res = {}
    if not os.path.exists(p): return res
    import configparser
    cp = configparser.ConfigParser(inline_comment_prefixes=("#",), strict=False, interpolation=None)
    try:
        cp.read(p, encoding="utf-8-sig")
        for k in ("paleta", "modo"):
            v = cp.get("cores", k, fallback="").strip()
            if k == "modo": v = {"1": "claro", "0": "escuro", "2": "sistema"}.get(v, v)
            if v: res[k] = v
        v = cp.get("usuario", "frase", fallback="").strip()
        if v.lstrip("-").isdigit(): res["frase"] = int(v)
    except Exception: pass
    try:
        with open(p, "r", encoding="utf-8-sig") as f: texto = f.read()
        secao = ""
        for linha in texto.splitlines():
            s = linha.strip()
            if s.startswith("[") and "]" in s: secao = s[1:s.index("]")].strip().lower(); continue
            if secao == "usuario" and "=" in s:
                chave_u, valor_u = s.split("=", 1)[0].strip().lower(), s.split("=", 1)[1].strip()
                if chave_u == "nome":
                    nome = _limpar_nome_usuario(valor_u)
                    if nome: res["nome"] = nome
                elif chave_u in ("versao", "pasta_lote", "pasta_exportacao", "idioma", "icones") and valor_u: res[chave_u] = valor_u
                elif chave_u == "zoom" and valor_u.lstrip("-").isdigit(): res["zoom"] = int(valor_u)
    except Exception: pass
    return res


def _gravar_prefs_usuario(prefs):
    try:
        os.makedirs(PASTA_USUARIOS, exist_ok=True)
        _ocultar_pasta(PASTA_USUARIOS)
        linhas = [f"; Preferências do usuário {_usuario_atual()} - gravado pelo TabWon em "
                  f"{datetime.now().strftime('%d/%m/%Y %H:%M')}", "[cores]"]
        if prefs.get("paleta"): linhas.append(f"paleta = {prefs['paleta']}")
        if prefs.get("modo"):
            linhas.append(f"modo = {MODOS_COR_NUM.get(prefs['modo'], '1')}"
                          f"    # 1 claro, 0 escuro, 2 automático (conforme o sistema)")
        if any(prefs.get(k) not in (None, "") for k in ("nome", "frase", "versao", "pasta_lote", "pasta_exportacao", "zoom", "idioma", "icones")):
            linhas.append("[usuario]")
            if prefs.get("nome"): linhas.append(f"nome = {_limpar_nome_usuario(prefs['nome'])}")
            if prefs.get("frase") is not None: linhas.append(f"frase = {int(prefs['frase'])}")
            if prefs.get("versao"): linhas.append(f"versao = {prefs['versao']}")
            if prefs.get("zoom"): linhas.append(f"zoom = {int(prefs['zoom'])}")
            if prefs.get("idioma"): linhas.append(f"idioma = {prefs['idioma']}")
            if prefs.get("icones"): linhas.append(f"icones = {prefs['icones']}")
            if prefs.get("pasta_lote"): linhas.append(f"pasta_lote = {str(prefs['pasta_lote']).replace(chr(10), ' ')}")
            if prefs.get("pasta_exportacao"):
                linhas.append(f"pasta_exportacao = {str(prefs['pasta_exportacao']).replace(chr(10), ' ')}")
        with open(_arquivo_prefs(), "w", encoding="utf-8", newline="\r\n") as f: f.write("\n".join(linhas) + "\n")
        return True
    except Exception as ex:
        _log(f"Preferências: {ex}"); return False


def _excluir_prefs_usuario():
    p = _arquivo_prefs()
    if os.path.exists(p): os.remove(p)


class Tooltip:
    def __init__(self, widget, texto, delay=400):
        self.widget = widget; self.texto = texto; self.delay = delay
        self._after_id = None; self._top = None
        try:
            widget.bind("<Enter>", self._enter, add="+")
            widget.bind("<Leave>", self._leave, add="+")
            widget.bind("<ButtonPress>", self._leave, add="+")
        except Exception: pass
    def _enter(self, event=None):
        self._cancel()
        try: self._after_id = self.widget.after(self.delay, self._show)
        except Exception: pass
    def _leave(self, event=None):
        self._cancel(); self._hide()
    def _cancel(self):
        if self._after_id:
            try: self.widget.after_cancel(self._after_id)
            except Exception: pass
            self._after_id = None
    def _show(self):
        if self._top is not None: return
        try:
            w = self.widget
            if not w.winfo_viewable(): return
            self._top = tk.Toplevel(w)
            self._top.withdraw(); self._top.wm_overrideredirect(True)
            tk.Label(self._top, text=self.texto, background="#FFFDE7",
                     relief="solid", borderwidth=1, font=("Arial", 9),
                     justify="left", padx=6, pady=3, wraplength=460).pack()
            self._top.update_idletasks()
            tw_, th_ = self._top.winfo_reqwidth(), self._top.winfo_reqheight()
            wx, wy, wh = w.winfo_rootx(), w.winfo_rooty(), w.winfo_height()
            jan = w.winfo_toplevel()
            jx0, jy0 = jan.winfo_rootx(), jan.winfo_rooty()
            jx1, jy1 = jx0 + jan.winfo_width(), jy0 + jan.winfo_height()
            sw, sh = w.winfo_screenwidth(), w.winfo_screenheight()
            esq = min(jx0, 0) if jx0 < sw else jx0
            dir_ = max(jx1, sw) if jx0 < sw else jx1
            topo = min(jy0, 0) if jy0 < sh else jy0
            baixo = max(jy1, sh - 40) if jy0 < sh else jy1
            x = wx + 16; y = wy + wh + 4
            if x + tw_ > dir_ - 4: x = dir_ - tw_ - 4
            if x < esq + 2: x = esq + 2
            if y + th_ > baixo - 4:
                y = wy - th_ - 4
                if y < topo + 2: y = max(topo + 2, baixo - th_ - 4)
            self._top.wm_geometry(f"+{int(x)}+{int(y)}")
            self._top.deiconify(); self._top.lift()
        except Exception:
            try:
                if self._top is not None: self._top.destroy()
            except Exception: pass
            self._top = None
    def _hide(self):
        if self._top is not None:
            try: self._top.destroy()
            except Exception: pass
            self._top = None


def _adicionar_tooltip(widget, texto):
    try: Tooltip(widget, texto)
    except Exception: pass


_MB_ORIGINAIS = {n: getattr(messagebox, n) for n in ("showinfo", "showwarning", "showerror", "askyesno",
                                                     "askokcancel", "askyesnocancel", "askretrycancel",
                                                     "askquestion")}
_MB_ICONES = {"info": ("ℹ", "#1976D2"), "warning": ("⚠", "#FF9800"), "error": ("✖", "#F44336"),
              "question": ("?", "#1976D2")}


def _janela_mae(parent):
    cand = parent
    if cand is None:
        try:
            raiz = _TEMA.get("root") or tk._default_root
            g = raiz.grab_current() if raiz is not None else None
            cand = g or (raiz.focus_get() if raiz is not None else None) or raiz
        except Exception:
            cand = _TEMA.get("root") or tk._default_root
    try:
        cand = cand.winfo_toplevel()
        if not cand.winfo_exists() or not cand.winfo_viewable():
            cand = _TEMA.get("root") or tk._default_root
    except Exception:
        cand = _TEMA.get("root") or tk._default_root
    return cand


def _dialogo(titulo, mensagem, botoes, icone="info", parent=None, padrao=0, cancelar=None, detalhe=None):
    pai = _janela_mae(parent)
    if pai is None:
        raise RuntimeError("sem janela")
    anterior = None
    try: anterior = pai.grab_current()
    except Exception: pass
    res = {"v": cancelar}
    d = tk.Toplevel(pai)
    d.withdraw()
    d.title(titulo or "TabWon"); d.configure(bg=COR_FUNDO); d.resizable(False, False)
    try: d.transient(pai)
    except Exception: pass
    simb, cor = _MB_ICONES.get(icone, _MB_ICONES["info"])
    img_al = _icone_alerta(icone)
    cor_cab = {"warning": "#E65100", "error": "#C62828"}.get(icone, COR_CABECALHO)
    tk.Label(d, text=titulo or "TabWon", font=("Arial", 11, "bold"), bg=cor_cab, fg="white", anchor="w",
             padx=12, pady=6).pack(fill="x")
    corpo = tk.Frame(d, bg=COR_FUNDO, padx=18, pady=14); corpo.pack(fill="both", expand=True)
    if img_al is not None:
        l_al = tk.Label(corpo, image=img_al, bg=COR_FUNDO, anchor="n"); l_al._img = img_al
        l_al.grid(row=0, column=0, rowspan=2, sticky="n", padx=(0, 12))
    else:
        tk.Label(corpo, text=simb, font=("Arial", 22, "bold"), fg=cor, bg=COR_FUNDO, width=2,
                 anchor="n").grid(row=0, column=0, rowspan=2, sticky="n", padx=(0, 12))
    texto = str(mensagem or "")
    if detalhe: texto += "\n\n" + str(detalhe)
    linhas = texto.splitlines()
    if len(linhas) > 22 or len(texto) > 1800:
        ft = tk.Frame(corpo, bg=COR_FUNDO); ft.grid(row=0, column=1, sticky="nsew")
        tx = tk.Text(ft, width=70, height=18, wrap="word", font=("Arial", 10), relief="flat", bg=COR_FUNDO,
                     borderwidth=0, highlightthickness=0)
        sb = tk.Scrollbar(ft, command=tx.yview); tx.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y"); tx.pack(side="left", fill="both", expand=True)
        tx.insert("1.0", texto); tx.configure(state="disabled")
    else:
        tk.Label(corpo, text=texto, bg=COR_FUNDO, font=("Arial", 10), justify="left", anchor="w",
                 wraplength=520).grid(row=0, column=1, sticky="w")
    fb = tk.Frame(corpo, bg=COR_FUNDO); fb.grid(row=2, column=0, columnspan=2, sticky="e", pady=(16, 0))

    def _fim(v):
        res["v"] = v
        try: d.grab_release()
        except Exception: pass
        d.destroy()
    criados = []
    for i, (rot, val) in enumerate(botoes):
        prim = i == padrao
        b = tk.Button(fb, text=rot, width=max(10, len(rot) + 2), font=("Arial", 10, "bold" if prim else "normal"),
                      command=lambda v=val: _fim(v), cursor="hand2",
                      **({"bg": "#1976D2", "fg": "white", "activebackground": "#1565C0",
                          "activeforeground": "white"} if prim else {}))
        b.pack(side="left", padx=(0 if i == 0 else 6, 0))
        b.bind("<Return>", lambda e, v=val: _fim(v))
        criados.append(b)
    d.bind("<Escape>", lambda e: _fim(cancelar))
    d.protocol("WM_DELETE_WINDOW", lambda: _fim(cancelar))
    try:
        d.update_idletasks()
        w, h = d.winfo_reqwidth(), d.winfo_reqheight()
        sw, sh = d.winfo_screenwidth(), d.winfo_screenheight()
        if pai.winfo_viewable() and pai.winfo_width() > 1:
            x = pai.winfo_rootx() + (pai.winfo_width() - w) // 2
            y = pai.winfo_rooty() + (pai.winfo_height() - h) // 2
        else:
            x = (sw - w) // 2; y = (sh - h) // 2
        if pai.winfo_rootx() < sw:
            x = max(0, min(x, sw - w)); y = max(0, min(y, sh - h - 40))
        d.geometry(f"+{x}+{y}")
        d.deiconify(); d.lift()
        d.grab_set()
        alvo = criados[padrao] if 0 <= padrao < len(criados) else (criados[0] if criados else d)
        alvo.focus_force()
    except Exception: pass
    try: d.bell() if icone in ("error", "warning") else None
    except Exception: pass
    pai.wait_window(d)
    try:
        if anterior is not None and anterior.winfo_exists() and str(anterior) != str(d): anterior.grab_set()
    except Exception: pass
    try:
        if pai.winfo_exists(): pai.focus_force()
    except Exception: pass
    return res["v"]


def _mb_substituto(nome):
    def f(title=None, message=None, **opcoes):
        try:
            icone = opcoes.get("icon")
            padrao_kw = str(opcoes.get("default") or "").lower()
            parent = opcoes.get("parent"); detalhe = opcoes.get("detail")
            if nome == "showinfo":
                return _dialogo(title, message, [("OK", "ok")], icone or "info", parent, 0, "ok", detalhe)
            if nome == "showwarning":
                return _dialogo(title, message, [("OK", "ok")], icone or "warning", parent, 0, "ok", detalhe)
            if nome == "showerror":
                return _dialogo(title, message, [("OK", "ok")], icone or "error", parent, 0, "ok", detalhe)
            if nome == "askyesno":
                return bool(_dialogo(title, message, [("Sim", True), ("Não", False)], icone or "question", parent,
                                     1 if padrao_kw == "no" else 0, False, detalhe))
            if nome == "askquestion":
                return _dialogo(title, message, [("Sim", "yes"), ("Não", "no")], icone or "question", parent,
                                1 if padrao_kw == "no" else 0, "no", detalhe)
            if nome == "askokcancel":
                return bool(_dialogo(title, message, [("OK", True), ("Cancelar", False)], icone or "question",
                                     parent, 1 if padrao_kw == "cancel" else 0, False, detalhe))
            if nome == "askretrycancel":
                return bool(_dialogo(title, message, [("Tentar de novo", True), ("Cancelar", False)],
                                     icone or "warning", parent, 1 if padrao_kw == "cancel" else 0, False, detalhe))
            if nome == "askyesnocancel":
                return _dialogo(title, message, [("Sim", True), ("Não", False), ("Cancelar", None)],
                                icone or "question", parent,
                                {"no": 1, "cancel": 2}.get(padrao_kw, 0), None, detalhe)
        except Exception:
            pass
        return _MB_ORIGINAIS[nome](title, message, **opcoes)
    f.__name__ = nome
    return f


for _nome_mb in _MB_ORIGINAIS:
    setattr(messagebox, _nome_mb, _mb_substituto(_nome_mb))


_RE_DATA_ISO = re.compile(r'^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$')
_RE_DATA_BR = re.compile(r'^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$')
_RE_DATA_NUM = re.compile(r'^(\d{4})(\d{2})(\d{2})$')
_RE_DATA_NUM_DMY = re.compile(r'^(\d{2})(\d{2})(\d{4})$')


def parse_data_qualquer(txt):
    if txt is None: return None
    s = str(txt).strip()
    if not s: return None
    m = _RE_DATA_ISO.match(s)
    if m:
        try: return datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))).date()
        except Exception: pass
    m = _RE_DATA_BR.match(s)
    if m:
        try: return datetime(int(m.group(3)), int(m.group(2)), int(m.group(1))).date()
        except Exception: pass
    m = _RE_DATA_NUM.match(s)
    if m:
        try: return datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))).date()
        except Exception: pass
    m = _RE_DATA_NUM_DMY.match(s)
    if m:
        try: return datetime(int(m.group(3)), int(m.group(2)), int(m.group(1))).date()
        except Exception: pass
    return None


def formatar_br(valor):
    if pd.isna(valor): return ""
    try:
        num = float(valor)
        if not math.isfinite(num): return ""
        return (f"{int(num):,}".replace(",", ".") if num == int(num)
                else f"{num:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))
    except Exception: return str(valor)


def _formatar_numero(num, casas=0, milhar=True):
    try:
        if not math.isfinite(float(num)): return ""
    except Exception: return str(num)
    if casas > 0: s = f"{num:,.{casas}f}"
    else: s = f"{int(round(num)):,}"
    if milhar: s = s.replace(",", "X").replace(".", ",").replace("X", ".")
    else:
        s = s.replace(",", "")
        if casas > 0: s = s.replace(".", ",")
    return s


def _formatar_valor(valor, formato):
    if formato is None:
        return formatar_br(valor) if not isinstance(valor, str) else ("" if pd.isna(valor) else str(valor))
    tipo = formato.get("tipo", "")
    if pd.isna(valor) if not isinstance(valor, str) else (valor == ""): return ""
    if tipo == "data":
        fmt = formato.get("formato", "dd/mm/aaaa")
        if isinstance(valor, datetime): d = valor.date()
        elif isinstance(valor, date): d = valor
        else: d = parse_data_qualquer(valor)
        if d is None: return str(valor)
        try:
            mp = {"dd/mm/aaaa": "%d/%m/%Y", "aaaa-mm-dd": "%Y-%m-%d",
                  "aaaa/mm/dd": "%Y/%m/%d", "dd-mm-aaaa": "%d-%m-%Y",
                  "aaaammdd": "%Y%m%d", "ddmmaaaa": "%d%m%Y"}
            if fmt == "dia da semana":
                dias = ["segunda-feira", "terça-feira", "quarta-feira",
                        "quinta-feira", "sexta-feira", "sábado", "domingo"]
                return dias[d.weekday()]
            return d.strftime(mp.get(fmt, "%d/%m/%Y"))
        except Exception: return str(valor)
    if tipo == "moeda":
        casas = formato.get("casas", 2); milhar = formato.get("milhar", True)
        com_rs = formato.get("com_rs", True)
        try: num = float(valor)
        except Exception: return str(valor)
        s = _formatar_numero(num, casas, milhar)
        return f"R$ {s}" if com_rs else s
    if tipo == "numero":
        casas = formato.get("casas", 0); milhar = formato.get("milhar", False)
        pct = formato.get("porcento", False)
        try: num = float(valor)
        except Exception: return str(valor)
        s = _formatar_numero(num, casas, milhar)
        return s + "%" if pct else s
    if tipo == "texto": return "" if pd.isna(valor) else str(valor)
    return formatar_br(valor)


def _openpyxl_format(fmt):
    if not fmt: return None
    tipo = fmt.get("tipo", "")
    if tipo == "data":
        f = fmt.get("formato", "dd/mm/aaaa")
        return {"dd/mm/aaaa": "DD/MM/YYYY", "aaaa-mm-dd": "YYYY-MM-DD",
                "aaaa/mm/dd": "YYYY/MM/DD", "dd-mm-aaaa": "DD-MM-YYYY",
                "aaaammdd": "YYYYMMDD", "ddmmaaaa": "DDMMYYYY",
                "dia da semana": "DDDD"}.get(f, "DD/MM/YYYY")
    if tipo == "moeda":
        casas = fmt.get("casas", 2); milhar = fmt.get("milhar", True)
        mil = "#,##0" if milhar else "0"
        dec = "." + "0" * casas if casas > 0 else ""
        prefix = '"R$ " ' if fmt.get("com_rs", True) else ""
        return f'{prefix}{mil}{dec}'
    if tipo == "numero":
        casas = fmt.get("casas", 0); milhar = fmt.get("milhar", False)
        mil = "#,##0" if milhar else "0"
        dec = "." + "0" * casas if casas > 0 else ""
        base = f"{mil}{dec}"
        if fmt.get("porcento"): base = base + '"%"'
        return base
    return None


def _descricao_formato_legivel(fmt):
    if not fmt: return "sem formatação"
    t = fmt.get("tipo", "")
    if t == "data":
        s = f"data {fmt.get('formato','')}"
        if fmt.get("autoinc"):
            ai = fmt["autoinc"]
            s += f" autoinc {ai.get('valor')} {ai.get('nome_unidade')}"
        return s
    if t == "moeda":
        rs = "R$ " if fmt.get("com_rs", True) else ""
        mil = " c/ milhar" if fmt.get("milhar", True) else ""
        return f"moeda {rs}{fmt.get('casas',2)} casas{mil}"
    if t == "numero":
        pct = " %" if fmt.get("porcento") else ""
        mil = " c/ milhar" if fmt.get("milhar") else ""
        return f"número {fmt.get('casas',0)} casas{pct}{mil}"
    if t == "texto": return "texto"
    return t


def carregar_imagem_com_fundo(img_path, max_h, bg_hex=COR_FUNDO):
    if not HAS_PIL: return None
    bg_orig = bg_hex
    bg_hex = _para_hex(_traduzir_cor("f", bg_hex)) or bg_hex
    try:
        img = Image.open(img_path).convert('RGBA')
        ratio = max_h / img.height
        img = img.resize((int(img.width * ratio), max_h), Image.LANCZOS)
        arr = np.array(img).astype(np.int32)
        r, g, b, a = arr[:, :, 0], arr[:, :, 1], arr[:, :, 2], arr[:, :, 3]
        dist = np.sqrt(((r - 255) ** 2 + (g - 255) ** 2 + (b - 255) ** 2).astype(np.float64))
        mascara = (dist < 15) & (a > 200)
        bg_r = int(bg_hex[1:3], 16); bg_g = int(bg_hex[3:5], 16); bg_b = int(bg_hex[5:7], 16)
        arr[mascara, 0] = bg_r; arr[mascara, 1] = bg_g; arr[mascara, 2] = bg_b
        img_proc = Image.fromarray(arr.astype(np.uint8))
        fundo = Image.new('RGB', img_proc.size, (bg_r, bg_g, bg_b))
        fundo.paste(img_proc, (0, 0), img_proc)
        foto = ImageTk.PhotoImage(fundo)
        _IMAGENS_REG[str(foto)] = (img_path, max_h, bg_orig)
        return foto
    except Exception: return None


def _carregar_index():
    for tentativa in range(5):
        if not os.path.exists(INDEX_CACHE): return {}
        try:
            with open(INDEX_CACHE, "r", encoding="utf-8") as f: return json.load(f)
        except Exception:
            time.sleep(0.2 * (tentativa + 1))
    return {}


def _salvar_index(index):
    temp = INDEX_CACHE + f".{os.getpid()}.{threading.get_ident()}.tmp"
    try:
        with open(temp, "w", encoding="utf-8") as f: json.dump(index, f, indent=2)
        for tentativa in range(50):
            try:
                os.replace(temp, INDEX_CACHE); return
            except PermissionError:
                time.sleep(0.2)
        os.replace(temp, INDEX_CACHE)
    except Exception:
        try:
            if os.path.exists(temp): os.remove(temp)
        except Exception: pass


def _hash_rapido(caminho, chunk=1024 * 1024):
    h = hashlib.md5()
    try:
        size = os.path.getsize(caminho)
        with open(caminho, "rb") as f:
            h.update(f.read(chunk))
            if size > chunk * 2: f.seek(-chunk, 2); h.update(f.read(chunk))
        return h.hexdigest()
    except Exception: return None


def _limpar_orfaos():
    import shutil
    agora = time.time()
    with _CACHE_LOCK, _TravaArquivo(_TRAVA_INDEX):
        index = _carregar_index()
        validos = set(v.get("arquivo") for v in index.values())
        for arquivo in os.listdir(CACHE_DIR):
            caminho = os.path.join(CACHE_DIR, arquivo)
            try: idade = agora - os.path.getmtime(caminho)
            except Exception: continue
            if arquivo.startswith("tmp_"):
                if idade > 24 * 3600:
                    try:
                        if os.path.isdir(caminho): shutil.rmtree(caminho, ignore_errors=True)
                        else: os.remove(caminho)
                    except Exception: pass
                continue
            if arquivo.endswith(".parquet") and arquivo not in validos and idade > _IDADE_ORFAO:
                try: os.remove(caminho)
                except Exception: pass
    try: locais = os.listdir(CACHE_LOCAL)
    except OSError: locais = []
    for arquivo in locais:
        caminho = os.path.join(CACHE_LOCAL, arquivo)
        try:
            if agora - os.path.getmtime(caminho) > 7 * 24 * 3600:
                if os.path.isdir(caminho): shutil.rmtree(caminho, ignore_errors=True)
                else: os.remove(caminho)
        except Exception: pass


