_CNV_RICO = {}


def _codificacao_texto(caminho):
    try:
        with open(caminho, "rb") as f: dados = f.read()
    except Exception: return "latin-1"
    if dados.startswith(b"\xef\xbb\xbf"): return "utf-8-sig"
    if dados.isascii(): return "latin-1"
    try:
        dados.decode("utf-8"); return "utf-8"
    except UnicodeDecodeError:
        return "latin-1"


_RE_CAB_CNV = re.compile(r"^\s*(?:([A-Za-z])\s+)?(\d+)\s+(\d+)\s*([A-Za-z]*)")


def _limite_desc_cnv(cab):
    if (cab or {}).get("limite_desc"): return int(cab["limite_desc"])
    return 100 if str((cab or {}).get("prefixo", "")).upper() == "N" else 50


def _sequenciais_faltando(seqs, limite=16):
    faltam = []; total = 0; ant = 0
    for v in sorted(seqs):
        if v - ant > 1:
            total += v - ant - 1
            k = ant + 1
            while k < v and len(faltam) < limite: faltam.append(k); k += 1
        ant = v
    return faltam, total


def _texto_uma_linha(v):
    return re.sub(r"\s*[\r\n\t]+\s*", " ", str(v or "")).strip()


def _coluna_codigos_cnv(linhas, largo):
    if not largo: return 60
    cont = {}
    for l in linhas:
        s = l.rstrip()
        if not s or s.lstrip().startswith(";"): continue
        m = re.search(r"\s(\S+)$", s)
        if not m: continue
        cont[m.start(1)] = cont.get(m.start(1), 0) + 1
    if not cont: return 112
    return max(cont.items(), key=lambda kv: (kv[1], -kv[0]))[0]


def _resolver_caminho(caminho, pasta_def=None):
    if not caminho: return caminho
    c = caminho.strip()
    if os.path.exists(c): return c
    nome = os.path.basename(c.replace("\\", os.sep).replace("/", os.sep))
    for pasta in (pasta_def, PASTA_TABWIN):
        if pasta:
            alt = os.path.join(pasta, nome)
            if os.path.exists(alt): return alt
            try:
                for f in os.listdir(pasta):
                    if f.lower() == nome.lower(): return os.path.join(pasta, f)
            except Exception: pass
    return c


def _pasta_ci(pasta):
    if not pasta: return None
    try:
        if os.path.isdir(pasta): return pasta
    except Exception: return None
    pai, nome = os.path.split(pasta.rstrip("\\/"))
    if not nome or not pai or pai == pasta: return None
    base = _pasta_ci(pai)
    if not base: return None
    try:
        with os.scandir(base) as it:
            for e in it:
                if e.name.lower() == nome.lower() and e.is_dir(): return e.path
    except Exception: pass
    return None


def _arquivos_na_pasta(pasta, mascara):
    base = _pasta_ci(pasta)
    if not base: return []
    m = mascara.lower()
    magica = any(ch in m for ch in "*?[")
    achados = []
    try:
        with os.scandir(base) as it:
            for e in it:
                nm = e.name.lower()
                if fnmatch.fnmatchcase(nm, m) if magica else nm == m:
                    try:
                        if e.is_file(): achados.append(e.path)
                    except OSError: pass
    except Exception: pass
    return achados


def _listar_arquivos_def(spec, pasta_def=None):
    c = (spec or "").strip().strip('"').strip()
    if not c: return []
    c = c.replace("/", os.sep).replace("\\", os.sep)
    pasta, mascara = os.path.split(c)
    if not mascara: return []
    bases = [b for b in (pasta_def, PASTA_TABWIN) if b]
    candidatos = []
    if pasta:
        if os.path.isabs(pasta) or os.path.splitdrive(pasta)[0] or pasta.startswith(os.sep): candidatos.append(pasta)
        else: candidatos += [os.path.normpath(os.path.join(b, pasta)) for b in bases]
    candidatos += bases
    vistos = set()
    for cand in candidatos:
        try: chave = os.path.normcase(os.path.abspath(cand))
        except Exception: chave = cand
        if chave in vistos: continue
        vistos.add(chave)
        if not _pasta_ci(cand): continue
        unicos = {}
        for p in _arquivos_na_pasta(cand, mascara): unicos.setdefault(os.path.normcase(os.path.abspath(p)), p)
        return sorted(unicos.values(), key=lambda x: os.path.basename(x).lower())
    return []


def _dividir_spec(spec):
    partes = str(spec).split("|")
    return partes[0], (partes[1] if len(partes) > 1 else None), (partes[2] if len(partes) > 2 else None)


def _cnv_existe(spec):
    if not spec: return False
    return os.path.exists(_dividir_spec(spec)[0])


_CODEPAGES_DBF = {0x01: "cp437", 0x02: "cp850", 0x03: "cp1252", 0x57: "cp1252", 0x64: "cp852"}


def _ler_dbf_estrutura(caminho):
    import struct
    with open(caminho, "rb") as f: dados = f.read()
    n_reg, tam_cab, tam_reg = struct.unpack("<IHH", dados[4:12])
    cp = _CODEPAGES_DBF.get(dados[29], "latin-1")
    campos = []; pos = 1; i = 32
    while i + 32 <= tam_cab and dados[i] != 0x0D:
        nome = dados[i:i + 11].split(b"\0")[0].decode("latin-1").strip()
        campos.append({"nome": nome, "tipo": chr(dados[i + 11]), "pos": pos, "tam": dados[i + 16], "dec": dados[i + 17]})
        pos += dados[i + 16]; i += 32
    regs = []
    for r in range(n_reg):
        ini = tam_cab + r * tam_reg
        bloco = dados[ini:ini + tam_reg]
        if len(bloco) < tam_reg: break
        if bloco[:1] == b"*": continue
        regs.append({c["nome"]: bloco[c["pos"]:c["pos"] + c["tam"]].decode(cp, errors="replace").strip() for c in campos})
    return {"cabecalho": dados[:tam_cab], "tam_reg": tam_reg, "cp": cp, "campos": campos, "regs": regs}


def _ler_dbf_tabela(caminho):
    e = _ler_dbf_estrutura(caminho)
    return [c["nome"] for c in e["campos"]], e["regs"]


def _nova_estrutura_dbf(campos):
    import struct, datetime as _dt
    hoje = _dt.date.today()
    tam_cab = 32 + 32 * len(campos) + 1; tam_reg = 1 + sum(t for _, t in campos)
    cab = bytearray(32)
    cab[0] = 0x03; cab[1:4] = bytes([hoje.year % 100, hoje.month, hoje.day])
    cab[8:12] = struct.pack("<HH", tam_cab, tam_reg); cab[29] = 0x02
    pos = 1; lista = []
    for nome, tam in campos:
        d = bytearray(32)
        d[0:11] = nome.encode("ascii")[:10].ljust(11, b"\0"); d[11] = ord("C")
        d[12:16] = struct.pack("<I", pos); d[16] = tam
        cab += d; lista.append({"nome": nome, "tipo": "C", "pos": pos, "tam": tam, "dec": 0}); pos += tam
    cab += b"\x0d"
    return {"cabecalho": bytes(cab), "tam_reg": tam_reg, "cp": "cp850", "campos": lista, "regs": []}


def _campos_dbf_edicao(estrutura, chave=None, desc=None):
    nomes = [c["nome"] for c in estrutura["campos"]]
    maiusc = {n.upper(): n for n in nomes}
    cod = maiusc.get((chave or "").upper()) or (nomes[0] if nomes else None)
    des = maiusc.get((desc or "").upper())
    if not des:
        cands = [c for c in estrutura["campos"] if c["nome"] != cod and c["tipo"] == "C"]
        pref = [c for c in cands if re.match(r"(NO|DS|DE|NM|DESC)", c["nome"].upper())]
        escolha = pref or sorted(cands, key=lambda c: -c["tam"])
        des = escolha[0]["nome"] if escolha else cod
    return cod, des


def _ler_dbf_para_edicao(caminho, chave=None, desc=None):
    est = _ler_dbf_estrutura(caminho)
    cod, des = _campos_dbf_edicao(est, chave, desc)
    tam = {c["nome"]: c["tam"] for c in est["campos"]}
    cab = {"ncat": 0, "nchars": tam.get(cod) or 1, "flag": "L", "prefixo": ("N" if (tam.get(des) or 0) > 50 else ""),
           "codificacao": "latin-1", "comentarios": [], "comentarios_antes": [], "limite_desc": tam.get(des) or 50,
           "dbf": {"estrutura": est, "cod": cod, "desc": des}}
    linhas = [{"tipo": "linha", "sub": "", "seq": str(i), "desc": str(r.get(des, "")), "cods": str(r.get(cod, "")),
               "com": "", "_reg": r} for i, r in enumerate(est["regs"], 1)]
    return cab, linhas


def _gravar_dbf_estrutura(caminho, estrutura, regs):
    import struct, datetime as _dt
    cab = bytearray(estrutura["cabecalho"]); hoje = _dt.date.today()
    cab[1:4] = bytes([hoje.year % 100, hoje.month, hoje.day])
    cab[4:8] = struct.pack("<I", len(regs))
    corpo = bytearray()
    for reg in regs:
        bloco = bytearray(b" " * estrutura["tam_reg"])
        for c in estrutura["campos"]:
            v = str(reg.get(c["nome"], "") or "")
            b = v.encode(estrutura["cp"], errors="replace")[:c["tam"]]
            b = b.rjust(c["tam"]) if c["tipo"] in "NF" else b.ljust(c["tam"])
            bloco[c["pos"]:c["pos"] + c["tam"]] = b
        corpo += bloco
    provisorio = caminho + ".tmp_tabwon"
    with open(provisorio, "wb") as f: f.write(bytes(cab) + bytes(corpo) + b"\x1a")
    os.replace(provisorio, caminho)


def _campos_do_dbc(caminho):
    import struct
    try:
        with open(caminho, "rb") as f:
            cab = f.read(32)
            tam_cab = struct.unpack("<H", cab[8:10])[0]
            resto = f.read(max(0, tam_cab - 32))
    except Exception:
        return []
    campos = []
    for i in range(0, len(resto) - 31, 32):
        if resto[i] == 0x0D: break
        nome = resto[i:i + 11].split(b"\0")[0].decode("latin-1").strip()
        campos.append((nome, chr(resto[i + 11]), resto[i + 16], resto[i + 17]))
    return campos


_RE_RANGE_ALFA = re.compile(r'^([A-Za-z])(\d+)-([A-Za-z])(\d+)$')


def _expandir_codigo(p, n_chars, curto):
    ma = _RE_RANGE_ALFA.match(p)
    if ma and len(ma.group(2)) == len(ma.group(4)):
        if not curto:
            return [], (p.split("-")[0].upper(), p.split("-")[1].upper())
        k = len(ma.group(2)); l1, l2 = ord(ma.group(1).upper()), ord(ma.group(3).upper())
        if l2 < l1: l1, l2 = l2, l1
        cods = []
        for letra in range(l1, l2 + 1):
            lo = int(ma.group(2)) if letra == l1 else 0
            hi = int(ma.group(4)) if letra == l2 else 10 ** k - 1
            cods.extend(chr(letra) + str(n).zfill(k) for n in range(lo, hi + 1))
        return cods, None
    mr = _RE_RANGE.match(p)
    if mr and curto:
        ini, fim = int(mr.group(1)), int(mr.group(2))
        if fim < ini: ini, fim = fim, ini
        larg = n_chars or max(len(mr.group(1)), len(mr.group(2)))
        return [str(c).zfill(larg) for c in range(ini, fim + 1)], None
    if mr:
        return [], (mr.group(1), mr.group(2))
    return [p], None


def ler_cnv(spec):
    if not spec: return None
    caminho, chave_dbf, desc_dbf = _dividir_spec(spec)
    try: mt = os.path.getmtime(caminho)
    except Exception: return None
    ch = (spec, mt)
    if ch in _CNV_RICO: return _CNV_RICO[ch]
    res = {"n_chars": None, "literal": False, "faixas": False, "cats": [], "mapa": {},
           "codigos": {}, "intervalos": [], "pai": {}, "limites": [], "dbf": False}
    if caminho.lower().endswith(".dbf"):
        try:
            est = _ler_dbf_estrutura(caminho)
        except Exception as ex:
            _log(f"Tabela DBF ilegível {caminho}: {ex}"); _CNV_RICO[ch] = res; return res
        nomes, regs = [c["nome"] for c in est["campos"]], est["regs"]
        chave = next((n for n in nomes if chave_dbf and n.upper() == chave_dbf.upper()), nomes[0] if nomes else None)
        descc = next((n for n in nomes if desc_dbf and n.upper() == desc_dbf.upper()), None)
        if descc is None: descc = nomes[1] if len(nomes) > 1 else chave
        res["dbf"] = True; res["literal"] = True
        res["largura_chave"] = next((c["tam"] for c in est["campos"] if c["nome"] == chave), None)
        res["apelidos"] = {}
        for r in sorted(regs, key=lambda r: r.get(chave, "")):
            cod = r.get(chave, ""); texto = " ".join(str(r.get(descc, "")).split())
            if not cod or cod in res["mapa"]: continue
            desc = f"{cod} - {texto}" if texto and descc != chave else cod
            if texto and descc != chave: res["apelidos"].setdefault(texto, []).append(desc)
            res["mapa"][cod] = desc
            if desc not in res["codigos"]:
                res["codigos"][desc] = []; res["cats"].append(desc)
            res["codigos"][desc].append(cod)
        _CNV_RICO[ch] = res
        return res
    try:
        with open(caminho, "r", encoding=_codificacao_texto(caminho), errors="ignore") as f:
            linhas = f.read().splitlines()
    except Exception:
        _CNV_RICO[ch] = res; return res
    i_cab = None; largo = False
    for i, l in enumerate(linhas):
        s = l.strip()
        if not s or s.startswith(";"): continue
        m = _RE_CAB_CNV.match(l)
        if m:
            res["n_chars"] = int(m.group(3))
            flag = m.group(4).upper()
            res["literal"] = flag.startswith("L")
            res["faixas"] = flag.startswith("F")
            largo = (m.group(1) or "").upper() == "N"
            i_cab = i
        break
    if i_cab is None:
        _CNV_RICO[ch] = res; return res
    col = _coluna_codigos_cnv(linhas[i_cab + 1:], largo)
    lim_sub, lim_seq = (4, 9) if largo else (3, 8)
    n_chars = res["n_chars"]
    curto = bool(n_chars) and n_chars <= 4 and not res["literal"]
    rotulo_seq = {}; seq_ordem = []; seq_vistos = set(); usados = {}; desc_seq = {}; pai_seq = {}
    entradas = []
    for linha in linhas[i_cab + 1:]:
        if not linha.strip() or linha.lstrip().startswith(";"): continue
        m1 = re.match(r"\s*(\d+)", linha)
        if not m1: continue
        fim1 = m1.end()
        m2 = re.match(r"\s+(\d+)(?=\s|$)", linha[fim1:])
        if fim1 <= lim_sub and m2 and fim1 + m2.end() <= lim_seq:
            pai, seq = int(m1.group(1)), int(m2.group(1)); ini_desc = fim1 + m2.end()
        else:
            pai, seq = None, int(m1.group(1)); ini_desc = fim1
        while ini_desc < len(linha) and linha[ini_desc] == " ": ini_desc += 1
        if len(linha) > col and ini_desc < col - 1:
            desc = linha[ini_desc:col - 1].strip(); cods = linha[col:].strip()
        else:
            desc = linha[ini_desc:].strip(); cods = ""
        if not cods or (desc and re.search(r"\s{2,}\S", desc) and not linha[col - 1:col].isspace()):
            partes = re.split(r'\s{2,}', linha[ini_desc:].strip())
            if len(partes) > 1: desc = partes[0]; cods = partes[-1]
        desc_orig = " ".join(desc.split())
        if desc.startswith("."): desc = desc[1:].strip()
        desc = " ".join(desc.split())
        if ";" in cods: cods = cods.split(";")[0].strip()
        if seq not in seq_vistos: seq_vistos.add(seq); seq_ordem.append(seq)
        if desc or seq not in desc_seq: desc_seq[seq] = (desc, desc_orig)
        if pai is not None and pai != seq: pai_seq[seq] = pai
        entradas.append((seq, cods))
    for seq in seq_ordem:
        desc, desc_orig = desc_seq.get(seq, ("", ""))
        rot = desc or str(seq)
        if rot in usados and usados[rot] != seq:
            rot = desc_orig if desc_orig and desc_orig not in usados else f"{rot} ({seq})"
        usados.setdefault(rot, seq)
        rotulo_seq[seq] = rot
    res["pai"] = {rotulo_seq[s]: p for s, p in pai_seq.items()}
    for seq in sorted(seq_ordem):
        res["cats"].append(rotulo_seq[seq]); res["codigos"][rotulo_seq[seq]] = []
    res["pai"] = {r: rotulo_seq[p] for r, p in res["pai"].items() if p in rotulo_seq}
    if res["faixas"]:
        lim = []
        for seq, cods in entradas:
            for p in cods.replace(" ", "").split(","):
                try: v = float(p)
                except Exception: continue
                lim.append((v, rotulo_seq[seq])); res["codigos"][rotulo_seq[seq]].append(p)
                res["mapa"][p] = rotulo_seq[seq]
        res["limites"] = sorted(lim, key=lambda t: t[0])
        _CNV_RICO[ch] = res
        return res

    def _norm(cod):
        s = str(cod).strip()
        if not s or res["literal"]: return s
        if n_chars and s.isdigit():
            if len(s) < n_chars: return s.zfill(n_chars)
            if len(s) > n_chars: return s[:n_chars]
        elif n_chars and len(s) > n_chars: return s[:n_chars]
        return s
    for seq, cods in entradas:
        rot = rotulo_seq[seq]
        for p in cods.replace(" ", "").split(","):
            if not p: continue
            lista, intervalo = _expandir_codigo(p, n_chars, curto)
            if intervalo:
                res["intervalos"].append((intervalo[0], intervalo[1], rot))
                res["codigos"][rot].append(p); continue
            for c in lista:
                c = _norm(c)
                res["codigos"][rot].append(c)
                if curto or c not in res["mapa"]: res["mapa"][c] = rot
    _CNV_RICO[ch] = res
    return res


def parse_cnv(caminho_cnv):
    cnv = ler_cnv(caminho_cnv)
    if not cnv: return None, {}
    return cnv["n_chars"], cnv["mapa"]


def _cnv_itens(spec):
    cnv = ler_cnv(spec)
    if not cnv: return []
    return [(r, tuple(dict.fromkeys(cnv["codigos"].get(r, [])))) for r in cnv["cats"]]


def _cnv_rotulos_dos_codigos(spec, codigos):
    cnv = ler_cnv(spec)
    if not cnv: return sorted(codigos)
    cod = set(codigos); rot = []; cobertos = set()
    for r, cs in _cnv_itens(spec):
        if cs and all(c in cod for c in cs):
            rot.append(r); cobertos.update(cs)
    for c in sorted(cod - cobertos):
        r = cnv["mapa"].get(c, c)
        if r not in rot: rot.append(r)
    return rot


def _normalizar_codigos(serie, n_chars, pos=1):
    s = serie.astype(str)
    if pos and pos > 1: s = s.str.slice(pos - 1)
    s = s.str.strip().str.replace(r'\.0$', '', regex=True)
    if n_chars:
        s = s.str.slice(0, n_chars)
        mask_num = s.str.fullmatch(r'\d+')
        if mask_num.any():
            precisa = mask_num & (s.str.len() < n_chars)
            if precisa.any(): s = s.where(~precisa, s.str.zfill(n_chars))
    return s


def aplicar_cnv(serie, caminho_cnv, pos=1):
    cnv = ler_cnv(caminho_cnv) if caminho_cnv and _cnv_existe(caminho_cnv) else None
    if not cnv or not (cnv["mapa"] or cnv["limites"] or cnv["intervalos"]):
        if pos and pos > 1: return serie.astype(str).str.slice(pos - 1)
        return serie
    if cnv["faixas"]:
        bruto = serie.astype(str)
        if pos and pos > 1: bruto = bruto.str.slice(pos - 1)
        v = pd.to_numeric(bruto.str.strip().str.replace(",", ".", regex=False), errors="coerce")
        lims = [l for l, _ in cnv["limites"]]; rots = [r for _, r in cnv["limites"]]
        import numpy as _np
        idx = _np.searchsorted(_np.array(lims, dtype=float), v.to_numpy(dtype=float), side="left")
        validos = (~v.isna().to_numpy()) & (idx < len(lims))
        saida = _np.array([rots[i] if ok else None for i, ok in zip(idx, validos)], dtype=object)
        res = pd.Series(saida, index=serie.index)
        return res.fillna(serie.astype(str).str.strip())
    if cnv["literal"] or cnv["dbf"]:
        s = serie.astype(str)
        if pos and pos > 1: s = s.str.slice(pos - 1)
        s = s.str.strip()
        largura = cnv.get("largura_chave") if cnv["dbf"] else cnv["n_chars"]
        if largura: s = s.str.slice(0, largura)
    else:
        s = _normalizar_codigos(serie, cnv["n_chars"], pos)
    out = s.map(cnv["mapa"])
    if cnv["intervalos"] and out.isna().any():
        falta = out.isna()
        tam = s.str.len()
        for a, b, rot in cnv["intervalos"]:
            comp = s.where(tam >= len(a), s.str.ljust(len(a)))
            m = falta & (tam > 0) & (tam <= len(a)) & (comp >= a) & (comp <= b)
            if m.any():
                out = out.where(~m, rot); falta = falta & ~m
    return out.fillna(s)


ROTULO_NAO_CLASSIFICADOS = "Não classificados"
NOME_COLUNA_TOTAL = "Total tabulado"
MODOS_NAO_CLASSIFICADOS = {
    0: ("Ignorar", "O programa desconsidera todos os registros com valores inválidos ou ausentes nos campos "
                   "selecionados. Apenas os dados que correspondem às categorias válidas previstas no arquivo "
                   "de conversão entram na contagem da tabela."),
    1: ("Incluir", "O programa contabiliza os registros com valores inválidos ou em branco nos totais da tabela. "
                   "Todos esses registros são agrupados juntos em uma única linha ou coluna genérica chamada "
                   "\"Não classificados\", sem mostrar qual era o código inválido original."),
    2: ("Discriminar", "O programa inclui os registros inválidos na contagem e exibe detalhadamente cada código não "
                       "reconhecido encontrado no banco de dados. Isso permite identificar exatamente quais erros de "
                       "digitação, códigos obsoletos ou valores em branco existem na base."),
}


def _rotulos_validos_cnv(cnv):
    v = set(cnv.get("cats") or []) | set((cnv.get("mapa") or {}).values())
    for it in cnv.get("intervalos") or []:
        try: v.add(it[2])
        except Exception: pass
    for it in cnv.get("limites") or []:
        try: v.add(it[1])
        except Exception: pass
    return v


def _tratar_nao_classificados(serie, item, modo):
    if not item or not item.get("cnv") or not _cnv_existe(item["cnv"]): return serie, [], None
    cnv = ler_cnv(item["cnv"])
    if not cnv or not (cnv.get("cats") or cnv.get("mapa")): return serie, [], None
    inv = ~serie.isin(_rotulos_validos_cnv(cnv))
    if not inv.any(): return serie, [], inv
    if modo == 1:
        return serie.astype(object).where(~inv, ROTULO_NAO_CLASSIFICADOS), [ROTULO_NAO_CLASSIFICADOS], inv
    if modo == 2:
        bruto = serie[inv].astype(str).str.strip()
        bruto = bruto.where(~bruto.isin(["", "nan", "None", "NaN", "<NA>", "NaT"]), "(em branco)")
        rot = "Não classif. - " + bruto
        nova = serie.astype(object).copy(); nova[inv] = rot
        return nova, sorted(rot.unique().tolist()), inv
    return serie, [], inv


def _resolver_descricoes_cnv(descs, spec):
    cnv = ler_cnv(spec)
    mapa = (cnv or {}).get("mapa") or {}
    n_chars = (cnv or {}).get("n_chars")
    rot_cod = {}
    for r, cs in _cnv_itens(spec): rot_cod.setdefault(str(r).strip(), set()).update(cs)
    for c, d_ in mapa.items(): rot_cod.setdefault(str(d_).strip(), set()).add(c)

    def nz(t): return re.sub(r"\s+", " ", _normalizar_texto(t))
    por_nz = {}
    for r in rot_cod: por_nz.setdefault(nz(r), []).append(r)
    apelidos = (cnv or {}).get("apelidos") or {}
    for ap, rs in apelidos.items():
        for r in rs:
            if r in rot_cod and r not in por_nz.setdefault(nz(ap), []): por_nz[nz(ap)].append(r)
    descs = _reunir_rotulos(descs, list(rot_cod) + list(apelidos))
    rotulos, codigos, faltando = [], set(), []

    def usar(rs):
        for r in dict.fromkeys(rs):
            rotulos.append(r); codigos.update(rot_cod.get(r, ()))
    for t in descs:
        t0 = str(t).strip()
        if not t0: continue
        if t0 in rot_cod: usar([t0]); continue
        k = nz(t0)
        if k in por_nz: usar(por_nz[k]); continue
        m = re.match(r"^(\S+)\s+(.+)$", t0)
        token = m.group(1) if m else t0
        resto = nz(m.group(2)) if m else ""
        cands = [token]
        if n_chars:
            if token.isdigit() and len(token) < n_chars: cands.append(token.zfill(n_chars))
            cands.append(token[:n_chars])
        cods = [c for c in dict.fromkeys(cands) if c in mapa]
        if cods:
            for c in cods:
                codigos.add(c)
                r = str(mapa[c]).strip()
                if r not in rotulos: rotulos.append(r)
            continue
        pref = list(dict.fromkeys(r for kk, rs in por_nz.items() if kk.startswith(k) for r in rs))
        if len(pref) == 1: usar(pref); continue
        if resto:
            pref2 = list(dict.fromkeys(r for kk, rs in por_nz.items() if kk.startswith(resto) for r in rs))
            if len(pref2) == 1: usar(pref2); continue
        sub = list(dict.fromkeys(r for kk, rs in por_nz.items() if k in kk or kk in k for r in rs))
        if len(sub) == 1: usar(sub); continue
        faltando.append(t0)
    return list(dict.fromkeys(rotulos)), codigos, faltando


def _converter_serie(serie, item):
    pos = item.get("pos", 1) or 1
    if item.get("cnv"): return aplicar_cnv(serie, item["cnv"], pos)
    if pos > 1: return serie.astype(str).str.slice(pos - 1).str.strip()
    return serie


def _somar_sem_subtotais(df, subtotais):
    soma = df.sum(numeric_only=True)
    if not subtotais: return soma
    rotulos = set(df.index)
    for pai, filhos in subtotais.items():
        if pai not in rotulos: continue
        presentes = [f for f in filhos if f in rotulos]
        if presentes:
            soma = soma - df.loc[presentes].sum(numeric_only=True)
    return soma


def _aplicar_subtotais(pivot, cnv):
    if not cnv or not cnv.get("pai"): return pivot, {}
    filhos = {}
    for filho, pai in cnv["pai"].items(): filhos.setdefault(pai, []).append(filho)
    def prof(r, k=0):
        p = cnv["pai"].get(r)
        return prof(p, k + 1) if p and k < 50 else k
    ordem = sorted(cnv["pai"].keys(), key=lambda r: -prof(r))
    num = pivot.select_dtypes("number").columns
    for filho in ordem:
        pai = cnv["pai"][filho]
        if filho in pivot.index and pai in pivot.index:
            pivot.loc[pai, num] = pivot.loc[pai, num] + pivot.loc[filho, num]
    return pivot, filhos


TIPOS_DEF = {
    "A": "Arquivos de dados", "L": "Linha", "C": "Coluna", "S": "Seleção",
    "T": "Linha e Coluna", "D": "Linha (dupla)", "X": "Linha, Coluna e Seleção",
    "I": "Incremento", "G": "Dados grupados", "R": "Relatório (TABDOS)", "Q": "Quadro (TABDOS)",
}


def _arquivos_da_linha_a(padrao, pasta_def=None):
    return _listar_arquivos_def(padrao, pasta_def)


def _validar_cnv_arquivo(caminho):
    problemas = []
    try:
        with open(caminho, "r", encoding=_codificacao_texto(caminho), errors="ignore") as f: linhas = f.read().splitlines()
    except Exception as ex:
        return [("erro", f"não foi possível ler: {ex}")]
    cnv = ler_cnv(caminho)
    if not cnv or not cnv["n_chars"]:
        return [("erro", "primeira linha útil deve ter 'categorias caracteres' (ex.: 13 2)")]
    cab = next((l for l in linhas if l.strip() and not l.strip().startswith(";")), "")
    m = re.match(r"^\s*(?:[A-Za-z]\s+)?(\d+)", cab)
    declaradas = int(m.group(1)) if m else 0
    if declaradas and declaradas != len(cnv["cats"]):
        problemas.append(("aviso", f"cabeçalho diz {declaradas} categorias, mas há {len(cnv['cats'])}"))
    if not cnv["faixas"] and not cnv["dbf"]:
        n = cnv["n_chars"]
        ruins = [c for cs in cnv["codigos"].values() for c in cs
                 if "-" not in c and len(c) != n]
        if ruins:
            problemas.append(("aviso", f"{len(ruins)} código(s) com tamanho diferente de {n}: "
                                       + ", ".join(ruins[:5]) + ("…" if len(ruins) > 5 else "")))
    vazias = [r for r in cnv["cats"] if not cnv["codigos"].get(r) and r not in cnv["pai"].values()]
    if vazias:
        problemas.append(("aviso", f"{len(vazias)} categoria(s) sem códigos: " + ", ".join(vazias[:4])
                                   + ("…" if len(vazias) > 4 else "")))
    return problemas


def _analisar_def(texto, pasta_def):
    itens = []
    correcoes = []
    def add(n, nivel, msg, ref=None): itens.append((n, nivel, msg, ref))
    linhas = texto.splitlines()
    campos_dbc = {}
    arquivos_ok = False
    primeiro_dbc = None
    for n, bruta in enumerate(linhas, 1):
        if bruta[:1] == "A":
            arqs = _arquivos_da_linha_a(bruta[1:], pasta_def)
            if arqs:
                arquivos_ok = True
                add(n, "ok", f"{len(arqs)} arquivo(s) encontrado(s) para {bruta[1:].strip()}")
                if primeiro_dbc is None:
                    primeiro_dbc = sorted(arqs)[-1]
                    campos_dbc = {c[0].upper(): c for c in _campos_do_dbc(primeiro_dbc)}
            else:
                add(n, "erro", f"nenhum arquivo encontrado para {bruta[1:].strip()}")
    if not arquivos_ok:
        add(0, "erro", "o DEF não tem linha A com arquivos existentes")
    vistos_cnv = {}
    menus = {}
    grupos = {}
    for n, bruta in enumerate(linhas, 1):
        if not bruta.strip() or bruta.lstrip().startswith(";"): continue
        if bruta[:1] in (" ", "\t"):
            if re.match(r"^\s+[A-Za-z][^,]*,", bruta):
                add(n, "aviso", "linha começa com espaço: o TabWin e o TabWon a tratam como comentário")
                correcoes.append({"tipo": "comentar_espaco", "linhas": [n], "marcado": True,
                                  "desc": f"Linha {n}: começa com espaço (já é ignorada) → deixar explícito com ';'"})
            continue
        linha = bruta.strip()
        if linha.upper() == "X" or linha[:1] == "A": continue
        t = linha[0].upper()
        partes = [p.strip() for p in linha.split(",")]
        if t not in TIPOS_DEF:
            if len(partes) > 1: add(n, "aviso", f"tipo '{linha[0]}' desconhecido: linha ignorada")
            continue
        if t in ("R", "Q"):
            add(n, "info", f"tipo {t} ({TIPOS_DEF[t]}) não é usado pelo TabWon"); continue
        if t == "G":
            add(n, "aviso", "dados grupados (G) não são suportados pelo TabWon"); continue
        if len(partes) < 2:
            add(n, "erro", "faltam campos (formato: Tipo+Título, CAMPO[, posição, arquivo.cnv])"); continue
        titulo = partes[0][1:].strip(); campo = partes[1]
        if not titulo: add(n, "erro", "título vazio")
        if len(titulo) > 18:
            add(n, "info", f"título com {len(titulo)} caracteres (o TabWin exibe até 18)")
            correcoes.append({"tipo": "titulo", "linhas": [n], "marcado": False,
                              "desc": f"Linha {n}: abreviar o título para 18 caracteres → '{titulo[:18].strip()}'"})
        info_campo = campos_dbc.get(campo.upper()) if campos_dbc else None
        if campos_dbc and not info_campo:
            add(n, "erro", f"campo {campo} não existe em {os.path.basename(primeiro_dbc)}")
            correcoes.append({"tipo": "comentar", "linhas": [n], "marcado": True,
                              "desc": f"Linha {n}: o campo {campo} não existe nos DBCs → comentar a linha"})
        if t == "I":
            if info_campo and info_campo[1] not in ("N", "F"):
                add(n, "aviso", f"incremento {campo} não é numérico (tipo {info_campo[1]})")
            menus.setdefault(("I", _normalizar_texto(titulo)), []).append(n)
            continue
        pos = 1; cnv = None; dbf = None
        if len(partes) >= 3 and partes[2]:
            if partes[2].isdigit(): pos = int(partes[2])
            elif not partes[2].lower().endswith((".cnv", ".dbf")) and not any(p.lower().endswith(".dbf") for p in partes[2:]):
                add(n, "erro", f"posição inicial inválida: '{partes[2]}'")
        cnv = next((p for p in partes[2:] if p.lower().endswith(".cnv")), None)
        dbf = next((p for p in partes[2:] if p.lower().endswith(".dbf")), None)
        if cnv:
            r = _resolver_caminho(cnv, pasta_def)
            if not os.path.exists(r):
                add(n, "erro", f"CNV não encontrado: {cnv}", cnv)
                correcoes.append({"tipo": "comentar", "linhas": [n], "marcado": False,
                                  "desc": f"Linha {n}: CNV não encontrado ({os.path.basename(cnv)}) → comentar a linha"})
            else:
                if r.lower() not in vistos_cnv:
                    vistos_cnv[r.lower()] = _validar_cnv_arquivo(r)
                for nivel, msg in vistos_cnv[r.lower()]:
                    add(n, nivel, f"{os.path.basename(r)}: {msg}", r)
                c = ler_cnv(r)
                if info_campo and c and c["n_chars"] and not c["faixas"] and pos + c["n_chars"] - 1 > info_campo[2]:
                    add(n, "aviso", f"posição {pos} + {c['n_chars']} caracteres passa do tamanho do campo ({info_campo[2]})", r)
        elif dbf:
            r = _resolver_caminho(dbf, pasta_def)
            if not os.path.exists(r): add(n, "erro", f"tabela DBF não encontrada: {dbf}")
        elif len(partes) >= 4:
            add(n, "aviso", "último campo não é .CNV nem .DBF")
        destinos = {"L": "L", "C": "C", "S": "S", "T": "LC", "D": "L", "X": "LCS"}[t]
        for d in destinos: menus.setdefault((d, _normalizar_texto(titulo)), []).append(n)
        chave = (_normalizar_texto(titulo), campo.upper(), pos, (cnv or dbf or "").strip().lower())
        grupos.setdefault(chave, {})
        for d in destinos: grupos[chave].setdefault(d, []).append((n, t))
    for (menu, tit), ns in menus.items():
        if len(ns) > 1:
            nome = {"L": "Linhas", "C": "Colunas", "S": "Seleções", "I": "Incrementos"}[menu]
            add(ns[1], "aviso", f"título repetido em {nome} (linhas {', '.join(map(str, ns))})")
    sugestoes = []
    for chave, por_menu in grupos.items():
        if all(d in por_menu for d in "LCS"):
            linhas_src = sorted({n for d in "LCS" for n, t in por_menu[d] if t in ("L", "C", "S", "T", "D")})
            if any(t == "X" for d in "LCS" for _, t in por_menu[d]): continue
            if linhas_src:
                sugestoes.append(linhas_src)
                add(linhas_src[0], "sugestao",
                    f"linhas {', '.join(map(str, linhas_src))} definem L, C e S iguais: podem virar uma linha X")
                correcoes.append({"tipo": "unificar", "linhas": linhas_src, "marcado": True,
                                  "desc": f"Linhas {', '.join(map(str, linhas_src))}: unificar L, C e S em uma linha X"})
    itens.sort(key=lambda t: (t[0], {"erro": 0, "aviso": 1, "sugestao": 2, "info": 3, "ok": 4}[t[1]]))
    correcoes.sort(key=lambda c: c["linhas"][0])
    return itens, sugestoes, correcoes


def _aplicar_unificacoes_def(texto, sugestoes):
    linhas = texto.splitlines()
    inserir = {}
    for grupo in sugestoes:
        primeira = linhas[grupo[0] - 1].strip()
        nova = "X" + primeira[1:]
        inserir[grupo[0] - 1] = nova
        for n in grupo:
            if not linhas[n - 1].lstrip().startswith(";"):
                linhas[n - 1] = ";" + linhas[n - 1]
    saida = []
    for i, l in enumerate(linhas):
        if i in inserir: saida.append(inserir[i])
        saida.append(l)
    return "\n".join(saida)


def _ler_cnv_para_edicao(caminho):
    codificacao = _codificacao_texto(caminho)
    with open(caminho, "r", encoding=codificacao, errors="replace") as f:
        linhas = f.read().splitlines()
    cab = {"ncat": 0, "nchars": 1, "flag": "", "prefixo": "", "codificacao": codificacao,
           "comentarios": [], "comentarios_antes": []}
    linhas_dados = []
    i_cab = None
    for i, l in enumerate(linhas):
        s = l.strip()
        if not s or s.startswith(";"):
            if s: cab["comentarios_antes"].append(l)
            continue
        m = _RE_CAB_CNV.match(l)
        if m:
            cab["prefixo"] = (m.group(1) or "").upper()
            cab["ncat"] = int(m.group(2)); cab["nchars"] = int(m.group(3)); cab["flag"] = m.group(4)
            i_cab = i
        break
    if i_cab is None: return cab, []
    largo = cab["prefixo"] == "N"
    col = _coluna_codigos_cnv(linhas[i_cab + 1:], largo)
    lim_sub, lim_seq = (4, 9) if largo else (3, 8)
    inicio = True
    for l in linhas[i_cab + 1:]:
        if not l.strip():
            continue
        if l.lstrip().startswith(";"):
            if inicio: cab["comentarios"].append(l)
            else: linhas_dados.append({"tipo": "comentario", "sub": "", "seq": "", "desc": l.strip(), "cods": "", "com": ""})
            continue
        inicio = False
        m1 = re.match(r"\s*(\d+)", l)
        ant = linhas_dados[-1] if linhas_dados and linhas_dados[-1]["tipo"] == "linha" else None
        recuo = len(l) - len(l.lstrip())
        if ant is not None and not ant["cods"] and (not m1 or recuo > lim_seq or len(l.split()) == 1):
            txt = l.strip()
            if ";" in txt:
                txt, com = txt.split(";", 1); txt = txt.strip(); ant["com"] = com.strip()
            partes = re.split(r"\s{2,}", txt)
            parte_desc, parte_cod = txt, ""
            if re.fullmatch(r"[\w.\-]+(,[\w.\-]+)*", partes[-1]) and (len(partes) > 1 or re.search(r"\d", partes[-1])):
                parte_desc, parte_cod = " ".join(partes[:-1]), partes[-1]
            ant["desc"] = (ant["desc"] + " " + parte_desc).strip()
            ant["cods"] = parte_cod.replace(" ", "")
            cab["reparadas"] = cab.get("reparadas", 0) + 1
            continue
        if not m1:
            linhas_dados.append({"tipo": "comentario", "sub": "", "seq": "", "desc": ";" + l.strip(), "cods": "", "com": ""})
            continue
        fim1 = m1.end()
        m2 = re.match(r"\s+(\d+)(?=\s|$)", l[fim1:])
        if fim1 <= lim_sub and m2 and fim1 + m2.end() <= lim_seq:
            sub, seq, ini = m1.group(1), m2.group(1), fim1 + m2.end()
        else:
            sub, seq, ini = "", m1.group(1), fim1
        while ini < len(l) and l[ini] == " ": ini += 1
        if len(l) > col and ini < col - 1:
            desc = l[ini:col - 1].rstrip(); cods = l[col:].strip()
        else:
            desc = l[ini:].strip(); cods = ""
        if not cods or re.search(r"\s{2,}\S", desc):
            partes = re.split(r"\s{2,}", l[ini:].strip())
            if len(partes) > 1: desc, cods = partes[0], partes[-1]
        com = ""
        if ";" in cods:
            cods, com = cods.split(";", 1); cods = cods.strip(); com = com.strip()
        linhas_dados.append({"tipo": "linha", "sub": sub, "seq": seq, "desc": desc.strip(),
                             "cods": cods.replace(" ", ""), "com": com})
    return cab, linhas_dados


def _montar_texto_cnv(cab, linhas, ncat=None):
    seqs = {str(r["seq"]).strip() for r in linhas if r["tipo"] == "linha" and str(r["seq"]).strip()}
    if ncat is None:
        ncat = max(int(s) for s in seqs) if seqs and all(s.isdigit() for s in seqs) else len(seqs)
    out = list(cab.get("comentarios_antes", []))
    flag = (" " + cab["flag"]) if cab.get("flag") else ""
    largo = str(cab.get("prefixo", "")).upper() == "N"
    out.append(f"{'N ' if largo else ''}{ncat} {cab['nchars']}{flag}")
    out.extend(cab.get("comentarios", []))
    for r in linhas:
        if r["tipo"] == "comentario":
            t = _texto_uma_linha(r["desc"]); out.append(t if t.startswith(";") else ";" + t); continue
        desc = _texto_uma_linha(r["desc"])
        if largo:
            pref = f"{str(r['sub']).strip():>4}{str(r['seq']).strip():>5}  {desc[:100]:<100} "
        else:
            pref = f"{str(r['sub']).strip():>3}{str(r['seq']).strip():>4}  {desc[:50]:<50} "
        cods = [c for c in re.sub(r"\s+", "", str(r["cods"])).split(",") if c]
        blocos = []; atual = ""
        for c in cods:
            prox = (atual + "," + c) if atual else c
            if len(pref) + len(prox) > 255 and atual:
                blocos.append(atual); atual = c
            else:
                atual = prox
        blocos.append(atual)
        for k, b in enumerate(blocos):
            linha = pref + b
            if k == len(blocos) - 1 and r.get("com"): linha += f" ; {_texto_uma_linha(r['com'])}"
            out.append(linha.rstrip())
    return "\r\n".join(out) + "\r\n"


def _validar_linhas_cnv(cab, linhas):
    rel = []
    n = cab.get("nchars") or 0
    faixas = str(cab.get("flag", "")).upper().startswith("F")
    literal = str(cab.get("flag", "")).upper().startswith("L")
    lim = _limite_desc_cnv(cab)
    if n < 1: rel.append("Erro: informe o número de caracteres do código (≥ 1).")
    seqs = set(); dono = {}
    dados = [r for r in linhas if r["tipo"] == "linha"]
    for i, r in enumerate(dados, 1):
        s = str(r["seq"]).strip()
        if not s.isdigit(): rel.append(f"Erro: linha {i}: sequencial '{s}' não é número."); continue
        seqs.add(int(s))
        if not r["desc"].strip(): rel.append(f"Aviso: linha {i} (seq {s}): descrição vazia.")
        if len(r["desc"]) > lim: rel.append(f"Aviso: linha {i} (seq {s}): descrição com {len(r['desc'])} caracteres (máximo {lim}).")
        cods = [c for c in r["cods"].split(",") if c]
        if not cods and not str(r["sub"]).strip():
            rel.append(f"Aviso: linha {i} (seq {s}): sem códigos.")
        for c in cods:
            if faixas:
                try: float(c)
                except Exception: rel.append(f"Erro: linha {i} (seq {s}): limite '{c}' não é número (use ponto decimal).")
                continue
            partes = c.split("-") if ("-" in c and (not literal or all(len(x) == n for x in c.split("-")))) else [c]
            for p in partes:
                if n and len(p) != n:
                    rel.append(f"Aviso: linha {i} (seq {s}): código '{p}' tem {len(p)} caracteres (esperado {n})."); break
            if c in dono and dono[c] != s:
                rel.append(f"Aviso: código '{c}' aparece nos sequenciais {dono[c]} e {s} "
                           + ("(vale o último)." if (n and n <= 4 and not literal) else "(vale o primeiro)."))
            dono.setdefault(c, s)
    for r in dados:
        sub = str(r["sub"]).strip()
        if sub and (not sub.isdigit() or int(sub) not in seqs):
            rel.append(f"Erro: subtotal '{sub}' (seq {r['seq']}) aponta para um sequencial inexistente.")
    if faixas:
        lims = []
        for r in sorted(dados, key=lambda r: int(r["seq"]) if str(r["seq"]).isdigit() else 0):
            for c in r["cods"].split(","):
                try: lims.append(float(c))
                except Exception: pass
        if lims != sorted(lims): rel.append("Aviso: limites das faixas não estão em ordem crescente pelos sequenciais.")
    if seqs:
        faltam, _tot = _sequenciais_faltando(seqs)
        if faltam: rel.append(f"Info: sequenciais sem linha: {', '.join(map(str, faltam[:15]))}{'…' if len(faltam) > 15 else ''}.")
    return rel


def _aplicar_correcoes_def(texto, correcoes):
    linhas = texto.splitlines()
    comentadas = set()
    for c in correcoes:
        if c["tipo"] in ("comentar", "comentar_espaco"):
            for n in c["linhas"]:
                if not (1 <= n <= len(linhas)): continue
                l = linhas[n - 1]
                if l.lstrip().startswith(";"): continue
                linhas[n - 1] = ";" + (l.lstrip() if c["tipo"] == "comentar_espaco" else l)
                comentadas.add(n)
        elif c["tipo"] == "titulo":
            n = c["linhas"][0]
            if not (1 <= n <= len(linhas)) or n in comentadas: continue
            l = linhas[n - 1]
            partes = l.split(",", 1)
            if not partes[0]: continue
            novo = partes[0][0] + partes[0][1:].strip()[:18].strip()
            linhas[n - 1] = novo + ("," + partes[1] if len(partes) > 1 else "")
    grupos = [c["linhas"] for c in correcoes if c["tipo"] == "unificar" and not (set(c["linhas"]) & comentadas)]
    return _aplicar_unificacoes_def("\n".join(linhas), grupos)


def _problemas_linhas_cnv(cab, linhas):
    por_linha = {}; gerais = []
    def add(i, nivel, msg): por_linha.setdefault(i, []).append((nivel, msg))
    n = cab.get("nchars") or 0
    faixas = str(cab.get("flag", "")).upper().startswith("F")
    literal = str(cab.get("flag", "")).upper().startswith("L")
    curto = bool(n) and n <= 4 and not literal
    lim = _limite_desc_cnv(cab)
    eh_dbf = bool(cab.get("dbf"))
    larg_seq = 5 if str(cab.get("prefixo", "")).upper() == "N" else 4
    if n < 1: gerais.append(("Erro", "informe o número de caracteres do código (≥ 1)"))
    seqs = set(); dono = {}
    for i, r in enumerate(linhas):
        if r["tipo"] != "linha": continue
        s = str(r["seq"]).strip()
        if not s.isdigit(): add(i, "Erro", f"sequencial '{s}' não é número"); continue
        if not eh_dbf and len(s.lstrip("0")) > larg_seq:
            add(i, "Erro", f"sequencial '{s}' grande demais: parece um código numa linha quebrada"); continue
        seqs.add(int(s))
        if not r["desc"].strip(): add(i, "Aviso", "descrição vazia")
        if len(r["desc"]) > lim: add(i, "Aviso", f"descrição com {len(r['desc'])} caracteres (máximo {lim})")
        cods = [c for c in r["cods"].split(",") if c]
        if not cods and not str(r["sub"]).strip(): add(i, "Aviso", "sem códigos")
        if eh_dbf:
            if len(cods) > 1: add(i, "Erro", "a tabela DBF aceita um único código por linha")
            for c in cods:
                if n and len(c) > n: add(i, "Erro", f"código '{c}' tem {len(c)} caracteres (máximo {n})")
                if c in dono: add(i, "Aviso", f"código '{c}' repetido na linha #{dono[c] + 1}")
                dono.setdefault(c, i)
            continue
        for c in cods:
            if faixas:
                try: float(c)
                except Exception: add(i, "Erro", f"limite '{c}' não é número (use ponto decimal)")
                continue
            partes = c.split("-") if ("-" in c and (not literal or all(len(x) == n for x in c.split("-")))) else [c]
            for p in partes:
                if n and len(p) != n:
                    add(i, "Aviso", f"código '{p}' tem {len(p)} caracteres (esperado {n})"); break
            if c in dono and str(linhas[dono[c]]["seq"]).strip() != s:
                perde = dono[c] if curto else i
                add(perde, "Aviso", f"código '{c}' repetido na linha #{(i if perde == dono[c] else dono[c]) + 1}: "
                                    f"{'vale o último' if curto else 'vale o primeiro'}, este é ignorado")
            if curto or c not in dono: dono[c] = i
    for i, r in enumerate(linhas):
        if r["tipo"] != "linha": continue
        sub = str(r["sub"]).strip()
        if sub and (not sub.isdigit() or int(sub) not in seqs):
            add(i, "Erro", f"subtotal '{sub}' aponta para um sequencial inexistente")
    if faixas:
        lims = []
        for r in sorted([r for r in linhas if r["tipo"] == "linha"],
                        key=lambda r: int(r["seq"]) if str(r["seq"]).strip().isdigit() else 0):
            for c in r["cods"].split(","):
                try: lims.append(float(c))
                except Exception: pass
        if lims != sorted(lims): gerais.append(("Aviso", "os limites das faixas não estão em ordem crescente pelos sequenciais"))
    if seqs:
        faltam, _tot = _sequenciais_faltando(seqs)
        if faltam: gerais.append(("Info", f"sequenciais sem linha: {', '.join(map(str, faltam[:15]))}{'…' if len(faltam) > 15 else ''}"))
    return por_linha, gerais


def _reunir_rotulos(pecas, rotulos):
    norm = {_normalizar_texto(r) for r in rotulos}
    saida = []; i = 0; n = len(pecas)
    while i < n:
        achou = None
        for j in range(min(n, i + 8), i + 1, -1):
            for sep in (",", ", "):
                cand = sep.join(p.strip() for p in pecas[i:j])
                if _normalizar_texto(cand) in norm: achou = (j, cand); break
            if achou: break
        if achou: saida.append(achou[1]); i = achou[0]
        else: saida.append(pecas[i]); i += 1
    return list(dict.fromkeys(saida))


SQL_LOG_FILE = os.path.join(PASTA_CONFIGS, "TabWon_logs_sql.log")

SQL_LIMITE_TELA = 10000
SQL_AGREGACOES = ["", "SOMA", "CONTAGEM", "CONTAGEM DISTINTA", "MÉDIA", "MÍNIMO", "MÁXIMO"]
SQL_OPERADORES = ["igual a", "diferente de", "maior que", "maior ou igual a", "menor que",
                  "menor ou igual a", "está na lista", "não está na lista", "entre",
                  "começa com", "contém", "termina com", "é vazio", "não é vazio"]
SQL_DIRECOES = ["crescente", "decrescente", "ordem do CNV"]
_SQL_PROIBIDAS = ("INSERT", "UPDATE", "DELETE", "DROP", "CREATE", "ALTER", "COPY", "ATTACH",
                  "DETACH", "INSTALL", "LOAD", "PRAGMA", "SET", "RESET", "EXPORT", "IMPORT",
                  "CALL", "TRUNCATE", "VACUUM", "CHECKPOINT", "MERGE", "GRANT", "REVOKE", "USE",
                  "EXECUTE", "PREPARE", "DEALLOCATE", "BEGIN", "COMMIT", "ROLLBACK", "ABORT",
                  "UPSERT", "REPLACE INTO")
_SQL_FUNCOES_ARQUIVO = ("READ_CSV", "READ_CSV_AUTO", "READ_PARQUET", "PARQUET_SCAN", "READ_JSON",
                        "READ_JSON_AUTO", "READ_NDJSON", "READ_TEXT", "READ_BLOB", "GLOB",
                        "SNIFF_CSV", "PARQUET_METADATA", "PARQUET_SCHEMA", "GETENV", "READ_XLSX",
                        "ST_READ", "SQLITE_SCAN", "POSTGRES_SCAN", "MYSQL_SCAN", "DELTA_SCAN",
                        "ICEBERG_SCAN", "QUERY_TABLE", "QUERY")


def _sql_sem_textos(sql, manter_identificadores=False):
    saida = []; i = 0; n = len(sql)
    while i < n:
        c = sql[i]
        if c == "-" and sql[i:i + 2] == "--":
            j = sql.find("\n", i)
            i = n if j < 0 else j
            continue
        if c == "/" and sql[i:i + 2] == "/*":
            j = sql.find("*/", i + 2)
            i = n if j < 0 else j + 2
            saida.append(" "); continue
        if c == "'" or (c == '"' and not manter_identificadores):
            j = i + 1
            while j < n:
                if sql[j] == c:
                    if j + 1 < n and sql[j + 1] == c: j += 2; continue
                    break
                j += 1
            saida.append(" ''" if c == "'" else ' "_" '); i = j + 1; continue
        saida.append(c); i += 1
    return "".join(saida)


def _validar_sql_leitura(sql):
    if not sql or not sql.strip(): return False, "Escreva ou monte uma instrução SQL."
    limpo = _sql_sem_textos(sql).strip()
    while limpo.endswith(";"): limpo = limpo[:-1].rstrip()
    if ";" in limpo: return False, "Use apenas uma instrução SQL por vez (há mais de um ';')."
    primeira = re.match(r"\(*\s*([A-Za-z]+)", limpo)
    if not primeira or primeira.group(1).upper() not in ("SELECT", "WITH", "FROM", "VALUES"):
        return False, "Só são permitidas consultas de leitura (SELECT ou WITH)."
    alto = limpo.upper()
    for p in _SQL_PROIBIDAS:
        if re.search(r"\b" + p.replace(" ", r"\s+") + r"\b", alto):
            return False, f"Comando não permitido no Consultor SQL: {p}. Os DBCs são somente leitura."
    for f in _SQL_FUNCOES_ARQUIVO:
        if re.search(r"\b" + f + r"\s*\(", alto):
            return False, f"A função {f.lower()}() não é permitida: use as tabelas dos DBCs listados."
    if re.search(r"\bFROM\s+''", alto):
        return False, "Ler arquivos diretamente pelo caminho não é permitido: use as tabelas dos DBCs."
    return True, ""


def _sql_sem_ponto_virgula(sql):
    s = sql.strip()
    while s.endswith(";"): s = s[:-1].rstrip()
    return s


def _nome_tabela_dbc(caminho, existentes=()):
    base = re.sub(r"\W", "_", os.path.splitext(os.path.basename(caminho))[0]).upper() or "DBC"
    if base[0].isdigit(): base = "T_" + base
    nome = base; k = 2
    usados = {e.upper() for e in existentes}
    while nome.upper() in usados:
        nome = f"{base}_{k}"; k += 1
    return nome


def _sql_ident(nome):
    return '"' + str(nome).replace('"', '""') + '"'


def _sql_texto(v):
    return "'" + str(v).replace("'", "''") + "'"


def _sql_tabelas_usadas(sql, tabelas):
    limpo = _sql_sem_textos(sql, manter_identificadores=True).upper()
    usadas = {}
    for nome, caminho in tabelas.items():
        if re.search(r'(?<![\w])"?' + re.escape(nome.upper()) + r'"?(?![\w])', limpo):
            usadas[nome] = caminho
    return usadas


def _sql_tipo_duck(nome):
    try: return duckdb.type(nome)
    except Exception: return nome


def _udf_cnv(valores, specs, posicoes):
    import pyarrow as _pa
    try: spec = specs[0].as_py()
    except Exception: spec = None
    try: pos = int(posicoes[0].as_py() or 1)
    except Exception: pos = 1
    s = valores.to_pandas()
    nulos = s.isna()
    if not spec or not _cnv_existe(spec):
        r = s.astype(str).str.strip()
    else:
        r = aplicar_cnv(s.where(~nulos, ""), spec, pos).astype(str)
    r = r.where(~nulos, None)
    return _pa.array(r.tolist(), type=_pa.string())


def _udf_cnv_ordem(rotulos, specs):
    import pyarrow as _pa
    try: spec = specs[0].as_py()
    except Exception: spec = None
    ordem = {}
    if spec and _cnv_existe(spec):
        try: ordem = {c: i for i, c in enumerate(ler_cnv(spec)["cats"], 1)}
        except Exception: ordem = {}
    vals = rotulos.to_pylist()
    return _pa.array([ordem.get(v, 999999) if v is not None else 999999 for v in vals], type=_pa.int64())


def _sql_preparar_conexao(tabelas, cancelado=None, ao_converter=None):
    import pyarrow.dataset as _ds
    faltando = [c for c in tabelas.values() if not os.path.exists(c)]
    if faltando:
        raise RuntimeError("Arquivo não encontrado:\n" + "\n".join(faltando))
    precisa = [c for c in tabelas.values() if not _cache_valido(c)]
    if precisa and os.path.exists(CONVERSOR_EXE):
        erros = _converter_para_cache(precisa, cancelado, ao_converter)
        if erros:
            raise RuntimeError("Erro ao ler DBC:\n" + "\n".join(f"{os.path.basename(k)}: {v}" for k, v in erros.items()))
    con = duckdb.connect(":memory:")
    try:
        for nome, caminho in tabelas.items():
            pq = _cache_valido(caminho)
            if pq: con.register(nome, _ds.dataset(pq, format="parquet"))
            else: con.register(nome, _ler_dbc_com_cache(caminho))
        V = _sql_tipo_duck("VARCHAR"); B = _sql_tipo_duck("BIGINT")
        con.create_function("cnv", _udf_cnv, [V, V, B], V, type="arrow")
        con.create_function("cnv_ordem", _udf_cnv_ordem, [V, V], B, type="arrow")
        con.execute("SET enable_external_access = false")
        try: con.execute("SET lock_configuration = true")
        except Exception: pass
    except Exception:
        try: con.close()
        except Exception: pass
        raise
    return con


def _sql_valor(v, numerico):
    v = str(v).strip()
    if numerico:
        t = v.replace(".", "").replace(",", ".") if re.fullmatch(r"-?\d{1,3}(\.\d{3})+(,\d+)?|-?\d+,\d+", v) else v
        try:
            float(t); return t
        except Exception: pass
    return _sql_texto(v)


def _sql_lista_valores(valor):
    sep = ";" if ";" in valor else ","
    return [p.strip() for p in str(valor).split(sep) if p.strip()]


def _sql_coluna_expr(col):
    base = _sql_ident(col["campo"])
    ag = col.get("agreg", "")
    if ag == "SOMA": return f"SUM({base})"
    if ag == "MÉDIA": return f"AVG({base})"
    if ag == "MÍNIMO": return f"MIN({base})"
    if ag == "MÁXIMO": return f"MAX({base})"
    if ag == "CONTAGEM": return f"COUNT({base})"
    expr = _sql_coluna_valor(col)
    if ag == "CONTAGEM DISTINTA": return f"COUNT(DISTINCT {expr})"
    return expr


def _sql_coluna_valor(col):
    base = _sql_ident(col["campo"])
    pos = int(col.get("pos") or 1)
    if col.get("cnv"):
        return f"cnv(CAST({base} AS VARCHAR), {_sql_texto(col['cnv'])}, {pos})"
    if pos > 1: return f"substr(CAST({base} AS VARCHAR), {pos})"
    return base


def _sql_condicao(c, tipos):
    numerico = tipos.get(str(c.get("campo", "")).upper(), "C") in ("N", "F", "I", "B", "Y")
    if c.get("pelo_cnv") and c.get("cnv"):
        lhs = _sql_coluna_valor(c); numerico = False
    elif int(c.get("pos") or 1) > 1:
        lhs = f"trim(substr(CAST({_sql_ident(c['campo'])} AS VARCHAR), {int(c['pos'])}))"; numerico = False
    elif numerico:
        lhs = _sql_ident(c["campo"])
    else:
        lhs = f"trim(CAST({_sql_ident(c['campo'])} AS VARCHAR))"
    op = c.get("op", "igual a"); v = str(c.get("valor", ""))
    simples = {"igual a": "=", "diferente de": "<>", "maior que": ">", "maior ou igual a": ">=",
               "menor que": "<", "menor ou igual a": "<="}
    if op in simples: return f"{lhs} {simples[op]} {_sql_valor(v, numerico)}"
    if op in ("está na lista", "não está na lista"):
        itens = ", ".join(_sql_valor(x, numerico) for x in _sql_lista_valores(v)) or "''"
        return f"{lhs} {'NOT IN' if op.startswith('não') else 'IN'} ({itens})"
    if op == "entre":
        p = _sql_lista_valores(v)
        if len(p) < 2: p = (p + ["", ""])[:2]
        return f"{lhs} BETWEEN {_sql_valor(p[0], numerico)} AND {_sql_valor(p[1], numerico)}"
    txt = f"CAST({lhs} AS VARCHAR)" if numerico else lhs
    esc = v.replace("'", "''")
    if op == "começa com": return f"{txt} LIKE '{esc}%'"
    if op == "contém": return f"{txt} LIKE '%{esc}%'"
    if op == "termina com": return f"{txt} LIKE '%{esc}'"
    if op == "é vazio": return f"({lhs} IS NULL OR trim(CAST({lhs} AS VARCHAR)) = '')"
    if op == "não é vazio": return f"({lhs} IS NOT NULL AND trim(CAST({lhs} AS VARCHAR)) <> '')"
    return f"{lhs} = {_sql_valor(v, numerico)}"


def _sql_de_modelo(modelo):
    tabs = modelo.get("tabelas") or {}
    if not tabs: raise ValueError("Escolha pelo menos um arquivo DBC.")
    tipos = modelo.get("tipos") or {}
    usadas = [c for c in modelo.get("colunas", []) if c.get("usar")]
    if not usadas and not modelo.get("frequencia"):
        raise ValueError("Marque pelo menos uma coluna (ou a contagem de registros).")
    sel = []; tem_agreg = False; tem_grupo = False; aliases = {}
    for c in usadas:
        alias = (c.get("alias") or c["campo"]).strip()
        aliases[alias] = c
        if c.get("agreg"): tem_agreg = True
        else: tem_grupo = True
        sel.append(f"    {_sql_coluna_expr(c)} AS {_sql_ident(alias)}")
    if modelo.get("frequencia"):
        sel.append(f"    COUNT(*) AS {_sql_ident('Frequência')}"); tem_agreg = True
    nomes = list(tabs)
    if len(nomes) == 1: origem = _sql_ident(nomes[0])
    else:
        partes = "\n    UNION ALL BY NAME\n".join(f"    SELECT * FROM {_sql_ident(n)}" for n in nomes)
        origem = f"(\n{partes}\n) AS dados"
    sql = "SELECT\n" + ",\n".join(sel) + f"\nFROM {origem}"
    conds = [c for c in modelo.get("condicoes", []) if c.get("campo")]
    if conds:
        txt = []
        for i, c in enumerate(conds):
            lig = "" if i == 0 else (" OR " if c.get("lig") == "OU" else " AND ")
            txt.append(f"{lig}({_sql_condicao(c, tipos)})")
        sql += "\nWHERE " + "\n  ".join(txt)
    if tem_agreg and tem_grupo: sql += "\nGROUP BY ALL"
    ordens = []; por_cnv = False
    for o in modelo.get("ordem", []):
        alvo = o.get("expr", "")
        if not alvo: continue
        d = o.get("dir", "crescente")
        if d == "ordem do CNV" and alvo in aliases and aliases[alvo].get("cnv") and not aliases[alvo].get("agreg"):
            ordens.append(f"cnv_ordem({_sql_ident(alvo)}, {_sql_texto(aliases[alvo]['cnv'])})"); por_cnv = True
        else:
            ordens.append(_sql_ident(alvo) + (" DESC" if d == "decrescente" else ""))
    if por_cnv:
        sql = "SELECT * FROM (\n" + "\n".join("    " + l for l in sql.split("\n")) + "\n) AS resultado"
    if ordens: sql += "\nORDER BY " + ", ".join(ordens)
    try: lim = int(modelo.get("limite") or 0)
    except Exception: lim = 0
    if lim > 0: sql += f"\nLIMIT {lim}"
    return sql


def _ler_def_itens(caminho):
    with open(caminho, "r", encoding=_codificacao_texto(caminho), errors="ignore") as f: linhas = f.readlines()
    pasta_def = os.path.dirname(os.path.abspath(caminho))
    d = {"linhas": [], "colunas": [], "incrementos": [], "selecoes": [], "dbcs": [], "path_a": ""}
    dbcs = set()
    for linha in linhas:
        bruta = linha.replace('﻿', '').replace('\xa0', ' ').rstrip("\r\n")
        if not bruta.strip() or bruta[:1] in (" ", "\t"): continue
        linha = bruta.strip()
        if linha.startswith(";") or linha.upper() == "X": continue
        if linha.startswith("A"):
            c = linha[1:].strip()
            if not d["path_a"]: d["path_a"] = c
            enc = _listar_arquivos_def(c, pasta_def)
            if enc: dbcs.update(enc)
            elif not any(ch in c for ch in "*?"): dbcs.add(c)
            continue
        partes = [p.strip() for p in linha.split(",")]
        if len(partes) < 2: continue
        t = partes[0][0].upper()
        nome = partes[0][1:].strip().split("-")[0].strip()
        col = partes[1]
        pos = int(partes[2]) if len(partes) >= 3 and partes[2].isdigit() and int(partes[2]) > 0 else 1
        arq_cnv = partes[-1] if len(partes) >= 3 and partes[-1].lower().endswith(".cnv") else None
        arq_dbf = next((p for p in partes[2:] if p.lower().endswith(".dbf")), None)
        cnv = None
        if arq_cnv: cnv = os.path.abspath(_resolver_caminho(arq_cnv, pasta_def))
        elif arq_dbf:
            campo_desc = partes[2] if len(partes) >= 4 and not partes[2].lower().endswith(".dbf") else ""
            cnv = f"{os.path.abspath(_resolver_caminho(arq_dbf, pasta_def))}|{col}|{campo_desc}"
        item = {"tipo": t, "nome": nome, "coluna": col, "cnv": cnv, "pos": pos}
        destinos = {"I": ["incrementos"], "L": ["linhas"], "C": ["colunas"], "S": ["selecoes"],
                    "T": ["linhas", "colunas"], "D": ["linhas"], "X": ["linhas", "colunas", "selecoes"]}.get(t, [])
        for dd in destinos: d[dd].append(item)
    d["dbcs"] = sorted(dbcs, key=lambda x: os.path.basename(x).lower(), reverse=True)
    return d


def _resolver_def_do_log(def_valor):
    if not def_valor: return None
    if os.path.exists(def_valor): return def_valor
    alt = os.path.join(PASTA_TABWIN, os.path.basename(def_valor))
    return alt if os.path.exists(alt) else None


def _modelo_de_log(texto):
    avisos = []
    p0 = _parse_log_tabwin(texto)
    def_valor = next((v.strip() for k, v in p0["opcoes"].items() if _normalizar_texto(k) == "def"), "")
    def_path = _resolver_def_do_log(def_valor)
    if not def_path: raise ValueError(f"DEF do log não encontrado: {def_valor or '(sem DEF)'}")
    itens = _ler_def_itens(def_path)
    nomes_sel = {_normalizar_texto(s["nome"]) for s in itens["selecoes"]}
    p = _parse_log_tabwin(texto, nomes_selecoes=nomes_sel)
    def achar(lista, nome):
        alvo = _normalizar_texto(nome)
        return next((it for it in itens[lista] if _normalizar_texto(it["nome"]) == alvo), None)
    tabelas = {}
    por_nome = {os.path.basename(x).upper(): x for x in itens["dbcs"]}
    for a in p["arquivos"]:
        a = a.strip()
        if not a.lower().endswith(".dbc"): continue
        caminho = por_nome.get(os.path.basename(a).upper()) or (a if os.path.exists(a) else None)
        if not caminho:
            avisos.append(f"arquivo do log não encontrado pelo DEF: {a}"); continue
        tabelas[_nome_tabela_dbc(caminho, tabelas)] = caminho
    if not tabelas and itens["dbcs"]:
        tabelas[_nome_tabela_dbc(itens["dbcs"][0])] = itens["dbcs"][0]
        avisos.append("o log não lista arquivos: usei o DBC mais recente do DEF")
    colunas = []; ordem = []
    li = achar("linhas", p["linhas"][0]) if p["linhas"] else None
    if p["linhas"] and not li: avisos.append(f"linha '{p['linhas'][0]}' não existe no DEF")
    co = None
    if p["colunas"] and _normalizar_texto(p["colunas"][0]) != _normalizar_texto("Não ativa"):
        co = achar("colunas", p["colunas"][0])
        if not co: avisos.append(f"coluna '{p['colunas'][0]}' não existe no DEF")
    for it in (li, co):
        if not it: continue
        alias = it["nome"]
        if any(c["alias"] == alias for c in colunas): alias += " (coluna)"
        colunas.append({"campo": it["coluna"], "usar": True, "alias": alias, "agreg": "",
                        "cnv": it["cnv"] or "", "pos": it["pos"]})
        ordem.append({"expr": alias, "dir": "ordem do CNV" if it["cnv"] and not _dividir_spec(it["cnv"])[0].lower().endswith(".dbf") else "crescente"})
    frequencia = False
    for nome_inc in (p["incrementos"] or ["Frequencia"]):
        if _normalizar_texto(nome_inc) == "frequencia": frequencia = True; continue
        it = achar("incrementos", nome_inc)
        if not it: avisos.append(f"incremento '{nome_inc}' não existe no DEF"); continue
        colunas.append({"campo": it["coluna"], "usar": True, "alias": it["nome"], "agreg": "SOMA",
                        "cnv": "", "pos": 1})
    condicoes = []
    for nome_sel, descs in p["selecoes"]:
        it = achar("selecoes", nome_sel)
        if not it: avisos.append(f"seleção '{nome_sel}' não existe no DEF"); continue
        if not descs or _normalizar_texto(descs[0]) == "nenhuma": continue
        if it["cnv"] and _cnv_existe(it["cnv"]):
            rots_ok, _cods, falt = _resolver_descricoes_cnv(descs, it["cnv"])
            if falt: avisos.append(f"seleção '{nome_sel}': não encontrado(s) no CNV: {'; '.join(falt[:6])}")
            descs = rots_ok or descs
        condicoes.append({"lig": "E", "campo": it["coluna"], "op": "está na lista",
                          "valor": "; ".join(descs), "pelo_cnv": bool(it["cnv"]),
                          "cnv": it["cnv"] or "", "pos": it["pos"], "titulo": it["nome"]})
    tipos = {}
    try:
        primeiro = next(iter(tabelas.values()))
        tipos = {c[0].upper(): c[1] for c in _campos_do_dbc(primeiro)}
    except Exception: pass
    modelo = {"tabelas": tabelas, "tipos": tipos, "colunas": colunas, "frequencia": frequencia,
              "condicoes": condicoes, "ordem": ordem, "limite": 0, "def": def_path}
    return modelo, avisos


def _titulo_def_seguro(t):
    t = re.sub(r"[,;]", " ", str(t)).replace("-", "–").strip()
    return re.sub(r"\s+", " ", t) or "Campo"


def _numero_br(v):
    try:
        f = float(v)
        s = f"{f:,.2f}" if abs(f - round(f)) > 1e-9 else f"{int(round(f)):,}"
        return s.replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception: return str(v)


def _faixas_para_condicao(c, dec):
    op = c.get("op"); p = _sql_lista_valores(c.get("valor", ""))
    passo = 10 ** (-int(dec or 0))
    try: nums = [float(x.replace(",", ".")) for x in p]
    except Exception: return None
    if not nums: return None
    fmt = lambda x: f"{x:.{int(dec or 0)}f}"
    teto = "999999999999"
    a = nums[0]
    if op == "maior que":
        cats = [(f"Até {_numero_br(a)}", fmt(a)), (f"Acima de {_numero_br(a)}", teto)]; alvo = [1]
    elif op == "maior ou igual a":
        cats = [(f"Menor que {_numero_br(a)}", fmt(a - passo)), (f"{_numero_br(a)} ou mais", teto)]; alvo = [1]
    elif op == "menor que":
        cats = [(f"Menor que {_numero_br(a)}", fmt(a - passo)), (f"{_numero_br(a)} ou mais", teto)]; alvo = [0]
    elif op == "menor ou igual a":
        cats = [(f"Até {_numero_br(a)}", fmt(a)), (f"Acima de {_numero_br(a)}", teto)]; alvo = [0]
    elif op == "entre" and len(nums) >= 2:
        b = nums[1]
        cats = [(f"Menor que {_numero_br(a)}", fmt(a - passo)), (f"De {_numero_br(a)} a {_numero_br(b)}", fmt(b)),
                (f"Acima de {_numero_br(b)}", teto)]; alvo = [1]
    else: return None
    return cats, [cats[i][0] for i in alvo]


def _texto_cnv_faixas(titulo, cats):
    linhas = [f"; Faixas de {titulo} - criado pelo Consultor SQL do TabWon",
              f"{len(cats)} {max(len(lim) for _, lim in cats)} F"]
    for i, (rot, lim) in enumerate(cats, 1):
        linhas.append(f"{'':>3}{i:>4}  {rot[:50]:<50} {lim}")
    return "\r\n".join(linhas) + "\r\n"


def _plano_def_de_modelo(modelo):
    avisos = []
    tabs = list((modelo.get("tabelas") or {}).values())
    if not tabs: raise ValueError("Escolha pelo menos um arquivo DBC.")
    campos = {}
    try: campos = {c[0].upper(): c for c in _campos_do_dbc(tabs[0])}
    except Exception: pass
    pastas = {os.path.dirname(t) for t in tabs}
    nomes = [os.path.basename(t) for t in tabs]
    if len(tabs) == 1: padrao = tabs[0]
    else:
        prefixo = os.path.commonprefix([n.upper() for n in nomes])
        prefixo = nomes[0][:len(prefixo)] or ""
        padrao = os.path.join(sorted(pastas)[0], prefixo + "*.dbc")
        if len(pastas) > 1: avisos.append("os DBCs estão em pastas diferentes: a linha A usa só a primeira pasta")
    def linha_var(letra, titulo, campo, pos, cnv):
        titulo = _titulo_def_seguro(titulo)
        if cnv:
            arq, chave, desc = _dividir_spec(cnv)
            if arq.lower().endswith(".dbf"): return f"{letra}{titulo}, {campo}, {desc or campo}, {arq}"
            return f"{letra}{titulo}, {campo}, {int(pos or 1)}, {cnv}"
        return f"{letra}{titulo}, {campo}, {int(pos or 1)}"
    linhas_def = [";Criado pelo Consultor SQL do TabWon", ";", "A" + padrao, ";"]
    titulos = {}
    cnvs_novos = []
    usadas = [c for c in modelo.get("colunas", []) if c.get("usar")]
    for c in usadas:
        if c.get("agreg") == "SOMA":
            linhas_def.append(f"I{_titulo_def_seguro(c.get('alias') or c['campo'])}, {c['campo']}")
        elif c.get("agreg"):
            avisos.append(f"agregação {c['agreg']} de {c['campo']} não existe no DEF (só SOMA vira incremento)")
    if any(c.get("agreg") == "SOMA" for c in usadas): linhas_def.append(";")
    for c in usadas:
        if c.get("agreg"): continue
        t = _titulo_def_seguro(c.get("alias") or c["campo"])
        titulos[(c["campo"].upper(), c.get("cnv") or "", int(c.get("pos") or 1))] = t
        linhas_def.append(linha_var("X", t, c["campo"], c.get("pos"), c.get("cnv")))
    selecoes = []
    lig_ou = any(c.get("lig") == "OU" for c in modelo.get("condicoes", [])[1:])
    if lig_ou: avisos.append("condições ligadas por OU não existem no TabWon: todas viram seleções (E)")
    vistos = set()
    for c in modelo.get("condicoes", []):
        if not c.get("campo"): continue
        campo = c["campo"].upper(); op = c.get("op")
        info = campos.get(campo)
        if campo in vistos:
            avisos.append(f"mais de uma condição em {c['campo']}: só a primeira vira seleção"); continue
        cnv = c.get("cnv") if c.get("pelo_cnv") else ""
        pos = int(c.get("pos") or 1)
        chave = (campo, cnv or "", pos)
        valores = _sql_lista_valores(c.get("valor", ""))
        if op in ("igual a", "está na lista") or (op in ("diferente de", "não está na lista") and cnv):
            if op in ("diferente de", "não está na lista"):
                fora = set(valores)
                valores = [r for r, _ in _cnv_itens(cnv) if r not in fora]
            t = titulos.get(chave)
            if not t:
                t = _titulo_def_seguro(c.get("titulo") or c["campo"])
                linhas_def.append(linha_var("S", t, c["campo"], pos, cnv))
                titulos[chave] = t
            selecoes.append((t, valores)); vistos.add(campo); continue
        if op in ("maior que", "maior ou igual a", "menor que", "menor ou igual a", "entre") and \
                info and info[1] in ("N", "F"):
            r = _faixas_para_condicao(c, info[3] if len(info) > 3 else 0)
            if r:
                cats, escolhidas = r
                t = _titulo_def_seguro(f"Faixa {c.get('titulo') or c['campo']}")
                nome_arq = f"FAIXA_{re.sub(r'[^A-Za-z0-9]+', '_', c['campo']).upper()}.cnv"
                cnvs_novos.append({"titulo": t, "campo": c["campo"], "arquivo": nome_arq,
                                   "texto": _texto_cnv_faixas(c["campo"], cats)})
                linhas_def.append(f"S{t}, {c['campo']}, 1, {{CNV:{nome_arq}}}")
                selecoes.append((t, escolhidas)); vistos.add(campo); continue
        avisos.append(f"a condição '{c['campo']} {op} {c.get('valor', '')}' não pode virar seleção do TabWon")
    return {"linhas": linhas_def, "cnvs": cnvs_novos, "selecoes": selecoes, "avisos": avisos,
            "padrao": padrao}


def _texto_def_do_plano(plano, caminhos_cnv):
    saida = []
    for l in plano["linhas"]:
        m = re.search(r"\{CNV:([^}]+)\}", l)
        if m: l = l.replace(m.group(0), caminhos_cnv.get(m.group(1), m.group(1)))
        saida.append(l)
    return "\n".join(saida) + "\n"


def _log_de_modelo(modelo, def_path, selecoes_plano=None):
    avisos = []
    itens = _ler_def_itens(def_path)
    def achar(lista, campo, cnv, pos):
        for it in itens[lista]:
            if it["coluna"].upper() == campo.upper() and (it["cnv"] or "") == (cnv or "") and int(it["pos"]) == int(pos or 1):
                return it
        return next((it for it in itens[lista] if it["coluna"].upper() == campo.upper()), None)
    grupos = [c for c in modelo.get("colunas", []) if c.get("usar") and not c.get("agreg")]
    somas = [c for c in modelo.get("colunas", []) if c.get("usar") and c.get("agreg") == "SOMA"]
    if not grupos: raise ValueError("É preciso pelo menos uma coluna sem agregação para ser a Linha da tabulação.")
    if len(grupos) > 2: avisos.append("o TabWon tabula Linha e Coluna: só as duas primeiras colunas foram usadas")
    li = achar("linhas", grupos[0]["campo"], grupos[0].get("cnv"), grupos[0].get("pos"))
    if not li: raise ValueError(f"o DEF não tem Linha para o campo {grupos[0]['campo']}")
    co = achar("colunas", grupos[1]["campo"], grupos[1].get("cnv"), grupos[1].get("pos")) if len(grupos) > 1 else None
    if len(grupos) > 1 and not co: avisos.append(f"o DEF não tem Coluna para {grupos[1]['campo']}: Coluna não ativa")
    incs = []
    if co:
        incs = ["Frequencia"]
        if somas: avisos.append("com Coluna ativa o TabWon só aceita o incremento Frequencia: somas ignoradas")
    else:
        if modelo.get("frequencia") or not somas: incs.append("Frequencia")
        for s in somas:
            it = next((i for i in itens["incrementos"] if i["coluna"].upper() == s["campo"].upper()), None)
            if it: incs.append(it["nome"])
            else: avisos.append(f"o DEF não tem incremento para {s['campo']}")
    linhas = [f"TabWon versão {VERSAO}", "", "[Opções]", f"DEF={def_path}"]
    if itens["path_a"]: linhas.append(f"PATH={itens['path_a']}")
    linhas.append(f"Linha={li['nome']}")
    linhas.append(f"Coluna={co['nome'] if co else 'Não ativa'}")
    for n in incs: linhas.append(f"Incremento={n}")
    linhas += ["Suprime_Linhas_Zeradas=true", "Suprime_Colunas_Zeradas=true", "Não_Classificados=0",
               "", "[Seleções_Ativas]"]
    sels = selecoes_plano
    if sels is None:
        sels = []
        for c in modelo.get("condicoes", []):
            if c.get("op") in ("igual a", "está na lista") and c.get("campo"):
                it = achar("selecoes", c["campo"], c.get("cnv") if c.get("pelo_cnv") else "", c.get("pos"))
                if it: sels.append((it["nome"], _sql_lista_valores(c.get("valor", ""))))
                else: avisos.append(f"o DEF não tem Seleção para {c['campo']}")
            elif c.get("campo"):
                avisos.append(f"condição '{c['campo']} {c.get('op')}' não vira seleção do TabWon")
    if sels:
        for t, vals in sels:
            t_def = next((i["nome"] for i in itens["selecoes"] if _normalizar_texto(i["nome"]) == _normalizar_texto(t.split("-")[0].strip())), t)
            linhas.append(f"{t_def}: {', '.join(vals)}")
    else: linhas.append("(Nenhuma)")
    linhas += ["", "[Arquivos]"]
    for c in (modelo.get("tabelas") or {}).values(): linhas.append(os.path.basename(c))
    return "\n".join(linhas), avisos


def _ler_sql_salvos():
    itens = []
    if not os.path.exists(SQL_LOG_FILE): return itens
    try:
        with open(SQL_LOG_FILE, "r", encoding="utf-8") as f:
            for l in f:
                l = l.strip()
                if not l: continue
                try:
                    e = json.loads(l)
                    if isinstance(e, dict) and e.get("sql"): itens.append(e)
                except Exception: continue
    except Exception: pass
    return itens


def _gravar_sql_salvos(itens):
    os.makedirs(os.path.dirname(SQL_LOG_FILE), exist_ok=True)
    tmp = f"{SQL_LOG_FILE}.{os.getpid()}.tmp"
    with _TravaArquivo(SQL_LOG_FILE + ".lock"):
        with open(tmp, "w", encoding="utf-8") as f:
            for e in itens: f.write(json.dumps(e, ensure_ascii=False) + "\n")
        for tentativa in range(25):
            try:
                os.replace(tmp, SQL_LOG_FILE); return
            except PermissionError:
                time.sleep(0.2)
        os.replace(tmp, SQL_LOG_FILE)


PREFIXO_SQL = "Q ▶ "


def _texto_consulta_sql(sql, tabelas, modelo=None):
    linhas_sql = [("-- " + l if re.fullmatch(r"\s*-{6,}\s*", l) else l) for l in _sql_sem_ponto_virgula(sql).splitlines()]
    partes = [f"TabWon versão {VERSAO}", "", "[SQL]", "Tabelas=" + json.dumps(tabelas or {}, ensure_ascii=False)]
    if modelo: partes.append("Modelo=" + json.dumps(modelo, ensure_ascii=False))
    partes.append("Consulta=")
    return "\n".join(partes + linhas_sql)


def _ler_consulta_sql(texto):
    if not texto or not re.search(r"(?m)^\[SQL\]\s*$", texto): return None
    corpo = re.split(r"(?m)^\[SQL\]\s*$", texto, maxsplit=1)[1]
    tabelas, modelo, sql, em_sql = {}, None, [], False
    for l in corpo.splitlines():
        if em_sql: sql.append(l); continue
        s = l.strip()
        if s.startswith("Tabelas="):
            try: tabelas = json.loads(s[8:])
            except Exception: tabelas = {}
        elif s.startswith("Modelo="):
            try: modelo = json.loads(s[7:])
            except Exception: modelo = None
        elif s.startswith("Consulta="):
            em_sql = True
            if s[9:].strip(): sql.append(s[9:])
    return {"tabelas": tabelas, "modelo": modelo, "sql": "\n".join(sql).strip()}


def _pedir_nome(pai, titulo, rotulo, inicial=""):
    res = {"v": None}
    j = tk.Toplevel(pai, bg=COR_FUNDO); j.title(titulo); j.transient(pai)
    try: j.grab_set()
    except Exception: pass
    tk.Label(j, text=rotulo, font=("Arial", 11, "bold"), bg=COR_FUNDO).pack(anchor="w", padx=24, pady=(18, 6))
    e = tk.Entry(j, font=("Arial", 11), width=64, bd=2, relief="solid")
    e.pack(padx=24, ipady=4, fill="x"); e.insert(0, inicial or "")
    def ok(_=None):
        v = e.get().strip()
        if v: res["v"] = v; j.destroy()
    e.bind("<Return>", ok); e.bind("<Escape>", lambda _: j.destroy())
    fb = tk.Frame(j, bg=COR_FUNDO); fb.pack(pady=14)
    tk.Button(fb, text="Cancelar", command=j.destroy, bg="#9E9E9E", fg="white", font=("Arial", 10), width=12).pack(side="left", padx=6)
    tk.Button(fb, text="✓ OK", command=ok, bg="#4CAF50", fg="white", font=("Arial", 10, "bold"), width=12).pack(side="left", padx=6)
    centralizar(j, pai)
    try: j.after_idle(lambda: (e.focus_force(), e.select_range(0, tk.END)))
    except Exception: pass
    j.wait_window()
    return res["v"]


_ORG = {"identificadores": []}
LIMITE_NOME_CONSULTA = 30


def _montar_nome_consulta(ident, nome):
    nome = " ".join(str(nome or "").split())[:LIMITE_NOME_CONSULTA]
    ident = " ".join(str(ident or "").split())
    if not nome: return ""
    return f"{ident} - {nome}" if ident else nome


def _separar_nome_consulta(completo):
    completo = str(completo or "")
    for ident in sorted(_ORG["identificadores"], key=len, reverse=True):
        pref = f"{ident} - "
        if completo.startswith(pref): return ident, completo[len(pref):]
    return "", completo


def _campos_nome_consulta(pai, inicial="", fonte=("Arial", 11)):
    f = tk.Frame(pai, bg=COR_FUNDO)
    idents = list(_ORG["identificadores"])
    ident0, nome0 = _separar_nome_consulta(inicial)
    var_id = tk.StringVar(value=(ident0 or (idents[0] if idents else "")))
    var_nome = tk.StringVar(value=nome0[:LIMITE_NOME_CONSULTA])
    col = 0
    if idents:
        tk.Label(f, text="Identificador", font=(fonte[0], fonte[1], "bold"), bg=COR_FUNDO).grid(row=0, column=0, sticky="w")
        cb = ttk.Combobox(f, textvariable=var_id, values=idents, state="readonly", width=22, font=fonte)
        cb.grid(row=1, column=0, sticky="w", padx=(0, 8), ipady=2)
        _adicionar_tooltip(cb, "Equipe ou grupo que organiza a lista de consultas salvas")
        col = 1
    tk.Label(f, text=f"Nome (até {LIMITE_NOME_CONSULTA} caracteres)", font=(fonte[0], fonte[1], "bold"),
             bg=COR_FUNDO).grid(row=0, column=col, sticky="w")
    e = tk.Entry(f, textvariable=var_nome, font=fonte, width=LIMITE_NOME_CONSULTA + 4, bd=2, relief="solid")
    def _cortar(*_):
        v = var_nome.get()
        if len(v) > LIMITE_NOME_CONSULTA: var_nome.set(v[:LIMITE_NOME_CONSULTA])
    var_nome.trace_add("write", _cortar)
    e.grid(row=1, column=col, sticky="w", ipady=3)
    prev = tk.Label(f, text="", font=(fonte[0], max(8, fonte[1] - 2)), bg=COR_FUNDO, fg="#555555")
    prev.grid(row=2, column=0, columnspan=2, sticky="w", pady=(4, 0))
    def _atualizar(*_):
        n = _montar_nome_consulta(var_id.get(), var_nome.get())
        prev.config(text=(f"Vai aparecer como:  {n}" if n else ""))
    var_id.trace_add("write", _atualizar); var_nome.trace_add("write", _atualizar); _atualizar()
    f.obter = lambda: _montar_nome_consulta(var_id.get(), var_nome.get())
    f.entrada = e
    return f


