def _calc_num(df, c):
    return pd.to_numeric(df[c], errors="coerce").astype(float)


def _calcular_coluna(chave, df_sem, cols, params):
    import numpy as _np
    p = params or {}
    idx = df_sem.index
    if chave == "sequencia":
        return {"valor": pd.Series(_np.arange(1, len(df_sem) + 1, dtype=float), index=idx)}
    if chave == "acumular":
        return {"valor": _calc_num(df_sem, cols[0]).fillna(0).cumsum()}
    if chave == "normalizar":
        met = p.get("metodo", "minmax"); saida = {}
        for k, c in enumerate(cols):
            s = _calc_num(df_sem, c)
            if met == "minmax":
                mn, mx = s.min(), s.max()
                r = (s - mn) / (mx - mn) if mx != mn else s * 0.0
            elif met == "z":
                dp = s.std(ddof=1)
                r = (s - s.mean()) / dp if dp and dp == dp else s * 0.0
            elif met == "pct":
                t = s.sum()
                r = s / t * 100 if t else s * _np.nan
            elif met == "indice":
                base = s.dropna().iloc[0] if s.notna().any() else _np.nan
                r = s / base * 100 if base else s * _np.nan
            else:
                mx = s.abs().max()
                r = s / mx if mx else s * 0.0
            saida[str(k)] = r
        return saida
    if chave == "absoluto":
        return {"valor": _calc_num(df_sem, cols[0]).abs()}
    if chave == "inteiro":
        return {"valor": _np.trunc(_calc_num(df_sem, cols[0]))}
    if chave == "arredondar":
        casas = int(p.get("casas", 0) or 0)
        from decimal import Decimal as _Dec, ROUND_HALF_UP as _RHU
        q = _Dec(1).scaleb(-casas)
        return {"valor": _calc_num(df_sem, cols[0]).apply(
            lambda x: float(_Dec(repr(float(x))).quantize(q, rounding=_RHU)) if x == x else x)}
    if chave == "indicador":
        esc = float(p.get("escala", 1) or 1); casas = int(p.get("casas", 2) or 0)
        num = _calc_num(df_sem, cols[0]); den = _calc_num(df_sem, cols[1])
        r = (num / den.where(den != 0)) * esc
        return {"valor": r.round(casas)}
    if chave in ("minimo", "maximo"):
        m = pd.concat([_calc_num(df_sem, c) for c in cols], axis=1)
        return {"valor": m.min(axis=1) if chave == "minimo" else m.max(axis=1)}
    if chave == "posicao":
        asc = p.get("ordem", "maior") == "menor"
        return {"valor": _calc_num(df_sem, cols[0]).rank(method="min", ascending=asc)}
    if chave == "variacao":
        s = _calc_num(df_sem, cols[0]); ant = s.shift(1)
        if p.get("modo", "absoluta") == "percentual":
            return {"valor": (s / ant.where(ant != 0) - 1) * 100}
        return {"valor": s - ant}
    raise ValueError(f"cálculo desconhecido: {chave}")


def _total_calculo(formula, cols, tot, df_sem, destino):
    chave = formula.get("calc"); p = formula.get("params") or {}
    if chave == "acumular": return tot(cols[0])
    if chave == "normalizar": return 100.0 if p.get("metodo") == "pct" else None
    if chave in ("absoluto", "inteiro", "arredondar"):
        return float(pd.to_numeric(df_sem[destino], errors="coerce").sum())
    if chave == "indicador":
        d = tot(cols[1])
        if not d: return None
        return round(tot(cols[0]) / d * float(p.get("escala", 1) or 1), int(p.get("casas", 2) or 0))
    if chave == "minimo": return min(tot(c) for c in cols)
    if chave == "maximo": return max(tot(c) for c in cols)
    return None


