def _treemap_retangulos(valores, x, y, w, h):
    tot = float(sum(valores))
    if tot <= 0 or not valores: return []
    areas = [v * w * h / tot for v in valores]
    res = []

    def _pior(linha, lado):
        s = sum(linha)
        if s <= 0 or lado <= 0: return float("inf")
        return max(lado * lado * max(linha) / (s * s), (s * s) / (lado * lado * min(linha)))
    i = 0
    while i < len(areas):
        lado = min(w, h)
        linha = [areas[i]]; j = i + 1
        while j < len(areas) and _pior(linha + [areas[j]], lado) <= _pior(linha, lado):
            linha.append(areas[j]); j += 1
        s = sum(linha)
        if w >= h:
            larg = s / h if h > 0 else 0; yy = y
            for a in linha:
                alt = a / larg if larg > 0 else 0
                res.append((x, yy, larg, alt)); yy += alt
            x += larg; w -= larg
        else:
            alt = s / w if w > 0 else 0; xx = x
            for a in linha:
                lg = a / alt if alt > 0 else 0
                res.append((xx, y, lg, alt)); xx += lg
            y += alt; h -= alt
        i = j
    return res

