            if not s: return
            c = est["condicoes"][int(s[0])]
            var_lig.set(c.get("lig", "E")); var_ccampo.set(c["campo"]); var_op.set(c["op"])
            var_valor.set(c.get("valor", "")); var_pelo.set(bool(c.get("pelo_cnv")))
            _atualizar_lig()
