        f_lsel = tk.Frame(a, bg=COR_FUNDO); f_lsel.pack(fill="x")
        tk.Label(f_lsel, text="Consulta salva:", bg=COR_FUNDO, font=("Arial", 9, "bold")).pack(side="left")
        logs_simples = [e for e in getattr(self, "saved_logs_entries", []) if not e.get("super")]
        cb_logs = ttk.Combobox(f_lsel, state="readonly", width=60, values=[e["nome"] for e in logs_simples])
        cb_logs.pack(side="left", padx=6)
